def profile(
    kind_label: str,
    usage: str,
    operations: str,
    stats: list[tuple[str, str, str]],
    filters: list[str],
    headers: list[str],
    rows: list[list[str]],
    details: list[tuple[str, str]],
    cards: list[tuple[str, str, str]],
    actions: tuple[str, str],
) -> dict[str, object]:
    return {
        "kind_label": kind_label,
        "usage": usage,
        "operations": operations,
        "stats": stats,
        "filters": filters,
        "headers": headers,
        "rows": rows,
        "details": details,
        "cards": cards,
        "actions": actions,
    }


