def profile_for(item: dict[str, str]) -> dict[str, object] | None:
    return PAGE_PROFILES.get(item.get("编号"))


def clean(value: object) -> str:
    text = "" if value is None else str(value).strip()
    for old, new in {
        "帐款": "账款",
        "应收帐款": "应收账款",
        "应付帐款": "应付账款",
        "帐号": "账号",
        "帐户": "账户",
    }.items():
        text = text.replace(old, new)
    return text


def safe_name(text: str) -> str:
    text = clean(text)
    for ch in '/\\:*?"<>| ':
        text = text.replace(ch, "")
    return text[:30]


def raw_title(item: dict[str, str]) -> str:
    return item["优化建设内容"] or item["老系统菜单/功能"]


def client_title(item: dict[str, str]) -> str:
    if item.get("编号") == "S06":
        return "拼团订单"
    if item.get("编号") == "F12":
        return "收款记录"
    if item.get("编号") == "F05":
        return "应收明细"
    if item.get("编号") == "F07":
        return "应付明细"
    title = raw_title(item)
    for suffix in ["保留增强", "升级", "重构", "保留"]:
        if title.endswith(suffix):
            title = title[: -len(suffix)]
    return title.strip(" /-")


def assign_display_numbers(items: list[dict[str, str]]) -> list[dict[str, str]]:
    visible_no = 0
    for item in items:
        if clean(item.get("补充页")) == "是":
            shown = clean(item.get("显示编号"))
            if not shown:
                base = f"{visible_no:02d}" if visible_no else "00"
                item["显示编号"] = f"{base}-A"
            continue
        visible_no += 1
        item["显示编号"] = f"{visible_no:02d}"
    return items


def create_guide_mobile_role_item(source: dict[str, str]) -> dict[str, str]:
    item = dict(source)
    item["编号"] = "D07-MINI"
    item["模块"] = "导游端"
    item["优化建设内容"] = "微信小程序报账与核销"
    item["老系统菜单/功能"] = "导游手机端/微信小程序报账与核销"
    item["具体功能"] = "导游首页、我的团队、今日带团、待报账、已到账备用金、退回补报、审核中、消息通知、我的团队列表、团号、团队名称、出团日期、天数、人数、计调、集合信息、报账状态、团队详情、行程单、团队名单、接送信息、用餐住宿提示、计调联系方式、备用金到账情况、上传票据、上传发票/截图、按费用类型拆分、填写实际支出、填写未用金额、费用说明、退回原因、需补材料、重新上传、重新提交、计调初审、财务复审、核销结果、差额退补结果、最终回写团队成本、导游结算、财务审核"
    item["交付说明"] = "作为正式导游角色端页面放在图册最后，用微信小程序长图原型说明导游在手机端如何查看团队、确认备用金到账、提交报账核销、处理退回补报并查看差额退补结果"
    item["显示编号"] = "68"
    return item


def display_no(item: dict[str, str], fallback_idx: int | None = None) -> str:
    value = clean(item.get("显示编号"))
    if value:
        return value
    if fallback_idx is None:
        return ""
    return f"{fallback_idx:02d}"


def output_prefix(item: dict[str, str], fallback_idx: int | None = None) -> str:
    shown = display_no(item, fallback_idx)
    return shown if shown else f"{fallback_idx:02d}" if fallback_idx is not None else ""


def image_filename(item: dict[str, str], fallback_idx: int | None = None) -> str:
    return f"{output_prefix(item, fallback_idx)}-{safe_name(item['模块'])}-{safe_name(client_title(item))}.png"


def find_font(size: int, bold: bool = False) -> ImageFont.FreeTypeFont:
    candidates = [
        "/System/Library/Fonts/PingFang.ttc",
        "/System/Library/Fonts/STHeiti Medium.ttc" if bold else "/System/Library/Fonts/STHeiti Light.ttc",
        "/Library/Fonts/Arial Unicode.ttf",
    ]
    for path in candidates:
        if path and Path(path).exists():
            return ImageFont.truetype(path, size)
    return ImageFont.load_default()


