def read_items() -> list[dict[str, str]]:
    wb = load_workbook(EXCEL_PATH, read_only=True, data_only=True)
    ws = wb["功能建设清单"]
    headers = [clean(c.value) for c in ws[4]]
    items: list[dict[str, str]] = []
    for row in ws.iter_rows(min_row=5, values_only=True):
        if not row[0]:
            continue
        items.append({headers[i]: clean(row[i]) for i in range(len(headers))})
    return items


def merge_customer_master_items(items: list[dict[str, str]]) -> list[dict[str, str]]:
    c01 = next((item for item in items if item.get("编号") == "C01"), None)
    c02 = next((item for item in items if item.get("编号") == "C02"), None)
    c04 = next((item for item in items if item.get("编号") == "C04"), None)
    if not c01 or not c02 or not c04:
        raise RuntimeError("Expected C01, C02 and C04 in Excel for customer master merge")

    merged = dict(c01)
    merged["覆盖编号"] = "C01、C02、C04"
    merged["合并说明"] = "已合并客户分类与客户等级、客户下单名称与正式主体确认功能"
    merged["具体功能"] = merge_text(c01["具体功能"], c02["具体功能"], c04["具体功能"])
    merged["交付说明"] = merge_text(c01["交付说明"], c02["交付说明"], c04["交付说明"])
    merged["解决问题"] = merge_text(c01["解决问题"], c02["解决问题"], c04["解决问题"])

    result: list[dict[str, str]] = []
    guide_mobile_role_item: dict[str, str] | None = None
