def merge_text(*values: str) -> str:
    parts: list[str] = []
    for value in values:
        for part in re_split(r"[。；;]+", clean(value)):
            part = part.strip(" ，,、。；;")
            if part and part not in parts:
                parts.append(part)
    return "；".join(parts)


def split_features(text: str, limit: int = 8) -> list[str]:
    placeholder = "__AB_LEVEL__"
    source = clean(text).replace("A/B客户等级", placeholder)
    parts = [clean(x).replace(placeholder, "A/B客户等级") for x in re_split(r"[、,，;；]+", source) if clean(x)]
    result: list[str] = []
    for item in parts:
        if item not in result:
            result.append(item)
    return result[:limit] or ["业务信息", "状态", "负责人", "附件"]


def classify(item: dict[str, str]) -> str:
    text = " ".join(item.values())
    module = item["模块"]
    title = raw_title(item)
    menu = item["老系统菜单/功能"]
    if module == "数据统计":
        return "统计类"
    if module == "系统设置":
        return "系统设置类"
    if module == "企业资料":
        if any(k in title + menu for k in ["角色", "部门", "员工"]):
            return "系统设置类"
        return "档案类"
    if module == "客户管理":
        if "授信" in title or "应收" in title or "应收" in menu:
            return "财务类"
        if "合同" in title or "正式主体" in title or "授权" in title:
            return "订单团队类"
        return "档案类"
    if module == "采购管理":
        if any(k in title + menu for k in ["车辆", "排班"]):
            return "计调类"
        return "档案类"
    if module == "销售管理":
        if any(k in title + menu for k in ["费用变更", "成本分摊"]):
            return "财务类"
        if any(k in title + menu for k in ["智能报价", "票务", "门票"]):
            return "计调类"
        return "订单团队类"
    if module == "计调操作":
        if any(k in title + menu for k in ["报账"]):
            return "财务类"
        return "计调类"
    if module == "财务管理":
        return "财务类"
    if any(k in text for k in ["统计", "报表", "进度看板"]):
        return "统计类"
    if any(k in text for k in ["参数", "权限", "日志", "通知", "预警配置", "审批流"]):
        return "系统设置类"
    if any(k in text for k in ["应收", "应付", "收款", "付款", "发票", "备用金", "结算", "成本", "返佣"]):
        return "财务类"
    if any(k in text for k in ["计调", "导游", "车辆", "房态", "住宿", "车调", "派车", "报账"]):
        return "计调类"
    if any(k in text for k in ["订单", "团队", "团期", "产品", "拼团", "游客", "报价", "合同"]):
        return "订单团队类"
    return "档案类"


def is_credit_page(item: dict[str, str]) -> bool:
    title = raw_title(item)
    return item.get("编号") == "C03" or ("授信" in title and "应收" in title)


def is_subject_page(item: dict[str, str]) -> bool:
    title = raw_title(item)
    return item.get("编号") == "C04" or ("下单名称" in title and "正式主体" in title)


def is_customer_contract_page(item: dict[str, str]) -> bool:
    title = raw_title(item)
    return item.get("编号") == "C05" or ("客户销售合同" in title)


def is_product_auth_page(item: dict[str, str]) -> bool:
    title = raw_title(item)
    return item.get("编号") == "C06" or ("可售产品授权" in title or "产品授权" in title)


def display_kind(item: dict[str, str], kind: str) -> str:
    item_profile = profile_for(item)
    if item_profile:
        return str(item_profile["kind_label"])
    if is_subject_page(item):
        return "主体确认类"
    if is_credit_page(item):
        return "授信风控类"
    if is_customer_contract_page(item):
        return "合同台账类"
    if is_product_auth_page(item):
        return "产品授权类"
    return kind


def page_usage(item: dict[str, str]) -> str:
    kind = classify(item)
    item_profile = profile_for(item)
    if item_profile:
        return str(item_profile["usage"])
    if is_subject_page(item):
        return "用于维护客户常用下单名称、业务别名与正式法律主体的对应关系。销售可按客户习惯名称接单，但合同、发票、授信、应收只能使用已确认的正式主体，避免账款、开票和合同主体混乱。"
    if item.get("编号") == "C01" and item.get("覆盖编号"):
        return "用于统一维护客户基础资料、客户分类等级、业务别名、正式主体、开票主体、结算主体和授信建议额度。客户等级只带出授信建议值，真正可用的正式授信额度必须由财务或管理层确认后，才进入订单和应收占用计算。"
    if is_customer_contract_page(item):
        return "用于管理客户销售合同台账，包括合同编号、合同主体、有效期、结款方式、合同文件、到期提醒和下单合同校验。销售下单时系统检查客户是否存在有效合同，合同过期、即将到期或未签合同时提醒、拦截或转审批。"
    if is_product_auth_page(item):
        return "用于维护客户可以销售或下单的产品范围。不同客户只能看到和选择已授权的产品、线路或团期，授权可设置有效期和状态，未授权或授权过期的产品在下单时不可选或需转审批。"
    feature_limit = 10 if item.get("编号") == "C01" and item.get("覆盖编号") else 4
    features = "、".join(split_features(item["具体功能"], feature_limit))
    delivery = clean(item["交付说明"]).rstrip("。")
    if kind == "档案类":
        return f"用于维护{features}等基础信息，支撑后续下单、排团、结算和统计。{delivery}。"
    if kind == "订单团队类":
        return f"用于管理{features}等业务信息，承接销售接单、合同确认和团队执行流转。{delivery}。"
    if kind == "计调类":
        return f"用于安排{features}等计调资源，集中查看确认状态、资源冲突和成本变化。{delivery}。"
    if kind == "财务类":
        return f"用于管理{features}等财务事项，联动订单、团队、凭证、收付款和账款状态。{delivery}。"
    if kind == "统计类":
        return f"用于汇总{features}等经营数据，支持按客户、团队、资源和财务口径查看结果。{delivery}。"
    return f"用于配置{features}等系统规则，支撑权限、审批、预警、消息和日志留痕。{delivery}。"


def page_operations(item: dict[str, str]) -> str:
    kind = classify(item)
    item_profile = profile_for(item)
    if item_profile:
        return str(item_profile["operations"])
    if is_credit_page(item):
        return "销售查看正式授信占用和可用额度，超限时发起放行申请；财务维护正式授信额度、冻结/解冻授信并核对应收占用；管理层审批超限放行和大额额度调整。"
    if is_subject_page(item):
        return "销售新增下单名称和业务别名；资料管理员绑定正式法律主体并上传证明附件；财务确认开票主体、结算主体、授信主体；未确认主体不得用于合同、发票、授信和应收。"
    if item.get("编号") == "C01" and item.get("覆盖编号"):
        return "新增/编辑客户档案，维护联系人、附件、负责人、客户分类、A/B等级、授信建议额度、正式法律主体、开票主体和结算主体；授信建议仅作财务审批参考，正式授信确认后才联动订单、应收和超限预警。"
    if is_customer_contract_page(item):
        return "新增客户销售合同，上传合同文件，维护合同有效期、结款方式和合同主体；处理续签/变更/作废；下单时自动校验合同状态，异常合同转主管或财务审批。"
    if is_product_auth_page(item):
        return "选择客户后添加授权产品，设置授权期限、授权状态和适用团期；可批量启用/停用授权；销售下单时系统只允许选择该客户已授权且在有效期内的产品。"
    if kind == "档案类":
        return "新增/编辑档案，上传附件，启用/停用资料，查看关联订单、合同、资源和账款记录。"
    if kind == "订单团队类":
        return "新增业务单，确认订单，补充游客名单，发起费用变更，提交合同或团队流转审批。"
    if kind == "计调类":
        return "安排导游、车辆、酒店、门票等资源，处理资源冲突，查看成本变化，提交计调或财务审核。"
    if kind == "财务类":
        return "审核应收应付和成本，核验凭证，退回补充资料，登记收付款，关联发票、冲抵和结算记录。"
    if kind == "统计类":
        return "筛选统计口径，查看指标明细，下钻到订单/团队/账款来源，导出报表用于经营会议。"
    return "配置业务参数、审批节点、预警规则、消息通知和权限范围，启用/停用规则并查看操作日志。"


def text_size(draw: ImageDraw.ImageDraw, text: str, font: ImageFont.FreeTypeFont) -> tuple[int, int]:
    box = draw.textbbox((0, 0), text, font=font)
    return box[2] - box[0], box[3] - box[1]


def wrap(draw: ImageDraw.ImageDraw, text: str, font: ImageFont.FreeTypeFont, max_width: int, max_lines: int | None = None) -> list[str]:
    lines: list[str] = []
    current = ""
    for ch in clean(text):
        candidate = current + ch
        if text_size(draw, candidate, font)[0] <= max_width or not current:
            current = candidate
        else:
            lines.append(current)
            current = ch
            if max_lines and len(lines) >= max_lines:
                return lines
    if current and (not max_lines or len(lines) < max_lines):
        lines.append(current)
    return lines


def draw_text(draw: ImageDraw.ImageDraw, xy: tuple[int, int], text: str, font: ImageFont.FreeTypeFont, fill: str, max_width: int | None = None, max_lines: int | None = None, line_gap: int = 6) -> int:
    x, y = xy
    if max_width is None:
        draw.text((x, y), clean(text), font=font, fill=fill)
        return y + text_size(draw, clean(text), font)[1]
    for line in wrap(draw, text, font, max_width, max_lines):
        draw.text((x, y), line, font=font, fill=fill)
        y += text_size(draw, line, font)[1] + line_gap
    return y


def rounded(draw: ImageDraw.ImageDraw, xy, radius=12, fill="#fff", outline=None, width=1):
    draw.rounded_rectangle(xy, radius=radius, fill=fill, outline=outline, width=width)


def rect(draw: ImageDraw.ImageDraw, xy, fill="#fff", outline=None, width=1):
    draw.rectangle(xy, fill=fill, outline=outline, width=width)


def badge(draw: ImageDraw.ImageDraw, x: int, y: int, text: str, color: str, bg: str, font=F12) -> int:
    tw, th = text_size(draw, text, font)
    rounded(draw, (x, y, x + tw + 20, y + 26), 13, bg)
    draw.text((x + 10, y + 6), text, font=font, fill=color)
    return x + tw + 28


def button(draw: ImageDraw.ImageDraw, x: int, y: int, text: str, primary=False, danger=False) -> int:
    if primary:
        fill, outline, color = COLORS["blue"], COLORS["blue"], "#ffffff"
    elif danger:
        fill, outline, color = "#ffffff", COLORS["red"], COLORS["red"]
    else:
        fill, outline, color = "#ffffff", COLORS["line"], COLORS["text"]
    tw, _ = text_size(draw, text, F13)
    rounded(draw, (x, y, x + tw + 28, y + 34), 8, fill, outline)
    draw.text((x + 14, y + 9), text, font=F13, fill=color)
    return x + tw + 38


def phase_colors(phase: str) -> tuple[str, str]:
    if phase == "P0":
        return COLORS["red"], COLORS["red_soft"]
    if phase == "P2":
        return COLORS["purple"], COLORS["purple_soft"]
    return COLORS["blue"], COLORS["blue_soft"]


def create_canvas() -> tuple[Image.Image, ImageDraw.ImageDraw]:
    img = Image.new("RGB", (W, H), COLORS["bg"])
    return img, ImageDraw.Draw(img)


def create_canvas_size(width: int, height: int) -> tuple[Image.Image, ImageDraw.ImageDraw]:
    img = Image.new("RGB", (width, height), COLORS["bg"])
    return img, ImageDraw.Draw(img)


def draw_shell(draw: ImageDraw.ImageDraw, item: dict[str, str]):
    rect(draw, (0, 0, SIDEBAR_W, H), COLORS["sidebar"])
    draw.text((24, 24), "MTravel", font=F22, fill="#ffffff")
    draw.text((24, 58), "旅游接待管理系统", font=F12, fill="#94a3b8")

    y = 112
    for module in MODULE_ORDER:
        active = module == item["模块"]
        fill = COLORS["blue"] if active else COLORS["sidebar"]
        color = "#ffffff" if active else "#cbd5e1"
        if active:
            rounded(draw, (14, y - 9, SIDEBAR_W - 14, y + 31), 10, fill)
        draw.text((30, y), module, font=F15, fill=color)
        y += 48

    rect(draw, (SIDEBAR_W, 0, W, TOPBAR_H), "#ffffff", COLORS["line"])
    draw.text((CONTENT_X, 18), "首页 / 原型图册 / 功能页面", font=F13, fill=COLORS["muted"])
    button(draw, W - 310, 12, "导出", False)
    button(draw, W - 232, 12, "刷新", False)
    rounded(draw, (W - 138, 12, W - 24, 42), 15, COLORS["soft"], COLORS["line"])
    draw.text((W - 122, 20), "演示账号", font=F12, fill=COLORS["muted"])


def draw_page_header(draw: ImageDraw.ImageDraw, item: dict[str, str], idx: int):
    title = client_title(item)
    draw.text((CONTENT_X, CONTENT_Y), title, font=F26, fill=COLORS["text"])
    x = CONTENT_X
    y = CONTENT_Y + 44
    color, bg = phase_colors(item["优先级"])
    x = badge(draw, x, y, item.get("覆盖编号") or item["编号"], color, bg, F12)
    x = badge(draw, x, y, PHASE_TEXT.get(item["优先级"], item["优先级"]), color, bg, F12)
    kind = classify(item)
    badge(draw, x, y, display_kind(item, kind), COLORS["blue2"], COLORS["blue_soft"], F12)
    primary, secondary = primary_actions_for_item(kind, item)
    bx = W - 300
    bx = button(draw, bx, CONTENT_Y + 8, primary, True)
    bx = button(draw, bx, CONTENT_Y + 8, secondary, False)
    button(draw, bx, CONTENT_Y + 8, "导出", False)


