def panel(draw: ImageDraw.ImageDraw, xy, title: str | None = None):
    rounded(draw, xy, 14, COLORS["panel"], COLORS["line"])
    if title:
        x1, y1, x2, _ = xy
        draw.text((x1 + 18, y1 + 15), title, font=F16, fill=COLORS["text"])
        draw.line((x1, y1 + 48, x2, y1 + 48), fill=COLORS["line"], width=1)


def input_box(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, label: str, value: str = ""):
    draw.text((x, y), label, font=F12, fill=COLORS["muted"])
    rounded(draw, (x, y + 20, x + w, y + 54), 8, "#ffffff", COLORS["line"])
    if value:
        draw_text(draw, (x + 12, y + 29), value, F13, COLORS["text"], w - 24, 1)


def draw_filters(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, fields: list[str]):
    panel(draw, (x, y, x + w, y + 116), "查询条件")
    col_w = (w - 150) // 4
    fx = x + 18
    fy = y + 62
    for idx, field in enumerate(fields[:4]):
        input_box(draw, fx + idx * (col_w + 16), fy - 24, col_w, field, "全部")
    bx = x + w - 122
    button(draw, bx, y + 68, "查询", True)


def table_headers(kind: str, features: list[str]) -> list[str]:
    if kind == "档案类":
        return ["名称", "客户分类/等级", "默认授信", "状态", "负责人"]
    if kind == "订单团队类":
        return ["业务单号", "客户/团队", "人数/金额", "当前状态", "负责人"]
    if kind == "计调类":
        return ["团队号", "资源类型", "安排对象", "确认状态", "成本状态"]
    if kind == "财务类":
        return ["团队/客户", "账款类型", "金额", "审核状态", "凭证"]
    if kind == "统计类":
        return ["统计对象", "指标", "本期", "同比", "状态"]
    return ["配置名称", "适用模块", "触发条件", "启停状态", "修改人"]


def headers_for(item: dict[str, str], kind: str) -> list[str]:
    item_profile = profile_for(item)
    if item_profile:
        return list(item_profile["headers"])
    if is_credit_page(item):
        return ["客户名称", "正式授信额度", "已占用", "可用额度", "风险状态"]
    if is_subject_page(item):
        return ["下单名称/别名", "正式法律主体", "可用于业务", "确认状态", "负责人"]
    if item.get("编号") == "C01" and item.get("覆盖编号"):
        return ["客户名称/别名", "正式主体", "分类/等级", "授信建议", "状态"]
    if is_customer_contract_page(item):
        return ["合同编号", "客户/合同主体", "有效期", "结款方式", "合同状态"]
    if is_product_auth_page(item):
        return ["客户名称", "授权产品/线路", "授权期限", "授权状态", "负责人"]
    return table_headers(kind, split_features(item["具体功能"]))


