def draw_table(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, h: int, item: dict[str, str], kind: str):
    panel(draw, (x, y, x + w, y + h), "数据列表")
    headers = headers_for(item, kind)
    rows = sample_rows(item, kind)
    col_widths = [0.24, 0.22, 0.19, 0.18, 0.17]
    tx = x + 18
    ty = y + 62
    rect(draw, (tx, ty, x + w - 18, ty + 38), COLORS["soft"])
    cx = tx
    for i, header in enumerate(headers):
        cw = int((w - 36) * col_widths[i])
        draw_text(draw, (cx + 10, ty + 11), header, F12, COLORS["muted"], cw - 12, 1)
        cx += cw
    ty += 46
    for ridx, row in enumerate(rows):
        row_bg = "#ffffff" if ridx % 2 == 0 else "#fbfdff"
        rect(draw, (tx, ty, x + w - 18, ty + 52), row_bg)
        draw.line((tx, ty + 52, x + w - 18, ty + 52), fill=COLORS["line2"], width=1)
        cx = tx
        for i, value in enumerate(row):
            cw = int((w - 36) * col_widths[i])
            color = COLORS["green"] if value in ["正常", "有效", "已确认", "已生成", "启用", "主体已确认", "已绑定", "已授权"] else COLORS["orange"] if value in ["待确认", "审批中", "待审核", "预警", "房态紧张", "车价偏高", "接近上限", "超限待批", "待财务确认", "待补证明", "暂不授信", "待授信确认", "无授信建议", "即将到期", "待生效"] else COLORS["red"] if value in ["已过期"] else COLORS["text"]
            draw_text(draw, (cx + 10, ty + 17), value, F13, color, cw - 12, 1)
            cx += cw
        ty += 52
    action_y = y + h - 52
    ax = x + 18
    item_profile = profile_for(item)
    if item.get("编号") == "P05":
        ax = button(draw, ax, action_y, "查看详情", False)
        ax = button(draw, ax, action_y, "查看团队", False)
        button(draw, ax, action_y, "派车/释放", True)
    elif item_profile:
        ax = button(draw, ax, action_y, "查看详情", False)
        primary, secondary = tuple(item_profile["actions"])
        ax = button(draw, ax, action_y, secondary, False)
        button(draw, ax, action_y, primary, True)
    elif is_credit_page(item):
        ax = button(draw, ax, action_y, "查看详情", False)
        ax = button(draw, ax, action_y, "发起超限申请", False)
        button(draw, ax, action_y, "财务调额", True)
    elif is_subject_page(item):
        ax = button(draw, ax, action_y, "查看详情", False)
        ax = button(draw, ax, action_y, "绑定正式主体", False)
        button(draw, ax, action_y, "提交确认", True)
    elif is_customer_contract_page(item):
        ax = button(draw, ax, action_y, "查看详情", False)
        ax = button(draw, ax, action_y, "上传合同", False)
        button(draw, ax, action_y, "合同校验", True)
    elif is_product_auth_page(item):
        ax = button(draw, ax, action_y, "查看详情", False)
        ax = button(draw, ax, action_y, "添加授权", False)
        button(draw, ax, action_y, "启用授权", True)
    else:
        ax = button(draw, ax, action_y, "查看详情", False)
        ax = button(draw, ax, action_y, "编辑", False)
        button(draw, ax, action_y, action_button(kind), True)


