def primary_actions(kind: str) -> tuple[str, str]:
    if kind == "档案类":
        return "保存档案", "查看关联"
    if kind == "订单团队类":
        return "确认订单", "补充资料"
    if kind == "计调类":
        return "提交审核", "处理冲突"
    if kind == "财务类":
        return "审核通过", "退回补充"
    if kind == "统计类":
        return "导出报表", "查看明细"
    return "保存规则", "查看日志"


def primary_actions_for_item(kind: str, item: dict[str, str]) -> tuple[str, str]:
    item_profile = profile_for(item)
    if item_profile:
        return tuple(item_profile["actions"])
    if is_credit_page(item):
        return "财务调额", "超限申请"
    if is_subject_page(item):
        return "提交确认", "绑定主体"
    if is_customer_contract_page(item):
        return "合同校验", "上传合同"
    if is_product_auth_page(item):
        return "启用授权", "添加授权"
    return primary_actions(kind)


def draw_operation_card(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, item_title: str, desc: str, tone: str):
    color = COLORS["orange"] if tone == "orange" else COLORS["green"] if tone == "green" else COLORS["blue"]
    bg = COLORS["orange_soft"] if tone == "orange" else COLORS["green_soft"] if tone == "green" else COLORS["blue_soft"]
    rounded(draw, (x, y, x + w, y + 58), 10, bg)
    draw.text((x + 14, y + 10), item_title, font=F13, fill=color)
    draw_text(draw, (x + 14, y + 34), desc, F10, COLORS["muted"], w - 28, 1, 4)


def draw_operation_strip(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, item: dict[str, str], kind: str):
    panel(draw, (x, y, x + w, y + 92), "页面操作")
    action_text = page_operations(item)
    draw_text(draw, (x + 18, y + 54), action_text, F13, COLORS["text"], w - 280, 2, 5)
    bx = x + w - 252
    item_profile = profile_for(item)
    if item_profile:
        primary, secondary = tuple(item_profile["actions"])
        bx = button(draw, bx, y + 52, secondary, False)
        button(draw, bx, y + 52, primary, True)
        return
    if is_credit_page(item):
        bx = button(draw, bx, y + 52, "发起超限申请", False)
        button(draw, bx, y + 52, "财务调额", True)
        return
    if is_subject_page(item):
        bx = button(draw, bx, y + 52, "绑定主体", False)
        button(draw, bx, y + 52, "提交确认", True)
        return
    if is_customer_contract_page(item):
        bx = button(draw, bx, y + 52, "上传合同", False)
        button(draw, bx, y + 52, "合同校验", True)
        return
    if is_product_auth_page(item):
        bx = button(draw, bx, y + 52, "添加授权", False)
        button(draw, bx, y + 52, "启用授权", True)
        return
    primary, secondary = primary_actions(kind)
    bx = button(draw, bx, y + 52, secondary, False)
    button(draw, bx, y + 52, primary, True)


def draw_detail_drawer(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, h: int, item: dict[str, str], kind: str):
    panel(draw, (x, y, x + w, y + h), "业务处理区")
    yy = y + 66
    draw.text((x + 18, yy), "当前选中", font=F15, fill=COLORS["text"])
    yy += 32
    for label, value in detail_lines(item, kind)[:4]:
        draw.text((x + 18, yy), label, font=F12, fill=COLORS["muted"])
        draw_text(draw, (x + 104, yy - 1), value, F13, COLORS["text"], w - 124, 1)
        yy += 30
    draw.line((x + 18, yy + 4, x + w - 18, yy + 4), fill=COLORS["line"], width=1)
    yy += 22
    section_title = "角色与操作权限" if is_credit_page(item) else "本页可处理"
    draw.text((x + 18, yy), section_title, font=F15, fill=COLORS["text"])
    yy += 32
    for title, desc, tone in operation_items(kind, item):
        draw_operation_card(draw, x + 18, yy, w - 36, title, desc, tone)
        yy += 66
    primary, secondary = primary_actions_for_item(kind, item)
    button(draw, x + 18, y + h - 48, primary, True)
    button(draw, x + 116, y + h - 48, secondary, False)


def draw_vehicle_calendar_drawer(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, h: int, item: dict[str, str], kind: str):
    panel(draw, (x, y, x + w, y + h), "车辆日历")
    yy = y + 64
    draw.text((x + 18, yy), "当前选中", font=F15, fill=COLORS["text"])
    yy += 32
    for label, value in detail_lines(item, kind)[:4]:
        draw.text((x + 18, yy), label, font=F12, fill=COLORS["muted"])
        draw_text(draw, (x + 104, yy - 1), value, F13, COLORS["text"], w - 124, 1)
        yy += 28

    legend_y = yy + 8
    legend = [("空闲", COLORS["green"], COLORS["green_soft"]), ("已占用", COLORS["blue"], COLORS["blue_soft"]), ("维修停用", COLORS["orange"], COLORS["orange_soft"])]
    lx = x + 18
    for label, color, bg in legend:
        rounded(draw, (lx, legend_y, lx + 76, legend_y + 24), 12, bg)
        draw.text((lx + 10, legend_y + 6), label, font=F10, fill=color)
        lx += 84

    cal_x = x + 18
    cal_y = legend_y + 42
    cal_w = w - 36
    draw.text((cal_x, cal_y), "2026-05 车辆占用日历", font=F15, fill=COLORS["text"])
    cal_y += 30
    days = ["05/16", "05/17", "05/18", "05/19", "05/20", "05/21", "05/22"]
    cell_gap = 6
    cell_w = (cal_w - cell_gap * 2) // 3
    cell_h = 54
    statuses = [
        ("05/16", "空闲", COLORS["green"], COLORS["green_soft"]),
        ("05/17", "空闲", COLORS["green"], COLORS["green_soft"]),
        ("05/18", "已占用", COLORS["blue"], COLORS["blue_soft"]),
        ("05/19", "已占用", COLORS["blue"], COLORS["blue_soft"]),
        ("05/20", "维修停用", COLORS["orange"], COLORS["orange_soft"]),
        ("05/21", "空闲", COLORS["green"], COLORS["green_soft"]),
        ("05/22", "空闲", COLORS["green"], COLORS["green_soft"]),
    ]
    for idx, (day, status, color, bg) in enumerate(statuses):
        cx = cal_x + (idx % 3) * (cell_w + cell_gap)
        cy = cal_y + (idx // 3) * (cell_h + cell_gap)
        rounded(draw, (cx, cy, cx + cell_w, cy + cell_h), 8, bg, COLORS["line"])
        draw.text((cx + 10, cy + 8), day, font=F12, fill=COLORS["muted"])
        draw.text((cx + 10, cy + 30), status, font=F13, fill=color)

    note_y = cal_y + 3 * (cell_h + cell_gap) + 6
    draw.line((x + 18, note_y, x + w - 18, note_y), fill=COLORS["line"], width=1)
    draw.text((x + 18, note_y + 18), "占用说明", font=F15, fill=COLORS["text"])
    draw_text(draw, (x + 18, note_y + 46), "05/18-05/19 已用于 HZ20260518-003 西湖宋城二日游；维修停用日期不可派车。", F12, COLORS["muted"], w - 36, 3)
    primary, secondary = primary_actions_for_item(kind, item)
    button(draw, x + 18, y + h - 48, primary, True)
    button(draw, x + 116, y + h - 48, secondary, False)


def draw_vehicle_calendar_page(item: dict[str, str], idx: int) -> Path:
    img, draw = create_canvas()
    draw_shell(draw, item)
    draw_page_header(draw, item, idx)

    y = CONTENT_Y + 88
    draw_stat_cards_for_item(draw, CONTENT_X, y, CONTENT_W - 300, item, classify(item))
    y += 100
    draw_filters(draw, CONTENT_X, y, CONTENT_W, list(profile_for(item)["filters"]))
    y += 136

    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, y + 500), "车辆日历")
    cal_x = CONTENT_X + 24
    cal_y = y + 66
    left_w = 190
    day_w = (CONTENT_W - 48 - left_w) // 7
    row_h = 76
    days = ["05/16", "05/17", "05/18", "05/19", "05/20", "05/21", "05/22"]
    rect(draw, (cal_x, cal_y, cal_x + left_w + day_w * 7, cal_y + 44), COLORS["soft"])
    draw.text((cal_x + 14, cal_y + 14), "车辆", font=F13, fill=COLORS["muted"])
    for i, day in enumerate(days):
        draw.text((cal_x + left_w + i * day_w + 14, cal_y + 14), day, font=F13, fill=COLORS["muted"])

    rows = [
        ("浙A·D2398 / 37座", [("空闲", "green"), ("空闲", "green"), ("已占用", "blue"), ("已占用", "blue"), ("维修停用", "orange"), ("空闲", "green"), ("空闲", "green")]),
        ("浙A·K5821 / 49座", [("空闲", "green"), ("已占用", "blue"), ("空闲", "green"), ("空闲", "green"), ("空闲", "green"), ("已占用", "blue"), ("空闲", "green")]),
        ("浙A·M7610 / 19座", [("维修停用", "orange"), ("维修停用", "orange"), ("空闲", "green"), ("空闲", "green"), ("空闲", "green"), ("空闲", "green"), ("冲突", "red")]),
        ("浙A·Q8196 / 37座", [("空闲", "green"), ("空闲", "green"), ("空闲", "green"), ("已占用", "blue"), ("已占用", "blue"), ("空闲", "green"), ("空闲", "green")]),
    ]
    tone_fill = {"green": COLORS["green_soft"], "blue": COLORS["blue_soft"], "orange": COLORS["orange_soft"], "red": COLORS["red_soft"]}
    tone_color = {"green": COLORS["green"], "blue": COLORS["blue"], "orange": COLORS["orange"], "red": COLORS["red"]}
    for ridx, (vehicle, statuses) in enumerate(rows):
        ry = cal_y + 44 + ridx * row_h
        rect(draw, (cal_x, ry, cal_x + left_w + day_w * 7, ry + row_h), "#ffffff" if ridx % 2 == 0 else "#fbfdff")
        draw.line((cal_x, ry + row_h, cal_x + left_w + day_w * 7, ry + row_h), fill=COLORS["line2"], width=1)
        draw_text(draw, (cal_x + 14, ry + 24), vehicle, F13, COLORS["text"], left_w - 24, 1)
        for i, (status, tone) in enumerate(statuses):
            cx = cal_x + left_w + i * day_w + 8
            rounded(draw, (cx, ry + 18, cx + day_w - 16, ry + 56), 8, tone_fill[tone], COLORS["line"])
            draw_text(draw, (cx + 8, ry + 30), status, F12, tone_color[tone], day_w - 32, 1)

    legend_y = y + 414
    lx = cal_x
    for label, tone in [("空闲", "green"), ("已占用", "blue"), ("维修停用", "orange"), ("冲突", "red")]:
        rounded(draw, (lx, legend_y, lx + 92, legend_y + 28), 14, tone_fill[tone])
        draw.text((lx + 14, legend_y + 8), label, font=F12, fill=tone_color[tone])
        lx += 104
    draw_text(draw, (cal_x, legend_y + 48), "点击已占用日期可查看团队号、团队名称、用车时段和司机；冲突日期需要计调处理后才可确认派车。", F13, COLORS["text"], CONTENT_W - 48, 2)
    button(draw, CONTENT_X + CONTENT_W - 218, y + 442, "返回列表", False)
    button(draw, CONTENT_X + CONTENT_W - 116, y + 442, "查看团队", True)

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


