def draw_logic_card(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, h: int, data: dict[str, str]):
    tone = data.get("tone", "blue")
    color = stat_tone_color(tone)
    bg = COLORS["red_soft"] if tone == "red" else COLORS["orange_soft"] if tone == "orange" else COLORS["blue_soft"]
    rounded(draw, (x, y, x + w, y + h), 16, "#ffffff", COLORS["line"])
    rounded(draw, (x + 16, y + 16, x + w - 16, y + 58), 12, bg)
    draw.text((x + 32, y + 27), data["name"], font=F20, fill=color)
    badge(draw, x + w - 140, y + 24, data["target"], color, "#ffffff", F10)
    info = [
        ("使用角色", data["role"]),
        ("什么时候能操作", data["when"]),
        ("点击后做什么", data["action"]),
        ("影响的数据", data["impact"]),
        ("风险/校验规则", data["rule"]),
    ]
    yy = y + 78
    label_w = 110
    for label, value in info:
        draw.text((x + 24, yy), label, font=F13, fill=COLORS["muted"])
        yy = draw_text(draw, (x + 24 + label_w, yy - 1), value, F14, COLORS["text"], w - label_w - 48, 2, 4)
        yy += 8


def draw_team_operation_button_detail_page(item: dict[str, str], idx: int) -> Path:
    height = 2500
    img, draw = create_canvas_size(W, height)
    draw_tall_shell(draw, item, height)
    draw_page_header(draw, item, idx)

    y = CONTENT_Y + 88
    draw_stat_cards_for_item(draw, CONTENT_X, y, CONTENT_W - 300, item, classify(item))
    y += 100

    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, height - y - 28), "普通按钮逻辑明细页")
    map_x = CONTENT_X + 22
    map_y = y + 58
    map_w = CONTENT_W - 44

    draw_tall_section_title(draw, map_x, map_y, "1. 普通按钮与业务数据按钮", "拆成卡片后，客户不用放大也能看清：谁能点、什么时候点、点完影响什么、跳到哪里。高风险按钮单独放在下一页。", map_w)

    card_y = map_y + 82
    card_w = (map_w - 22) // 2
    card_h = 244
    for i, data in enumerate(TEAM_OPERATION_BUTTON_LOGIC):
        x = map_x + (i % 2) * (card_w + 22)
        yy = card_y + (i // 2) * (card_h + 22)
        draw_logic_card(draw, x, yy, card_w, card_h, data)

    summary_y = card_y + 4 * (card_h + 22) + 20
    draw_tall_section_title(draw, map_x, summary_y, "2. 确认口径", "这页先确认普通按钮和业务数据按钮，高风险按钮下一页单独确认权限、二次确认和留痕。", map_w)
    card_y = summary_y + 74
    card_w = (map_w - 24) // 3
    cards = [
        ("普通入口", "电子合同、返回上页主要是查看或跳转。", "blue"),
        ("业务数据", "内部备注、复制团队、修改团队、收客订单、团队安排、导游报账会影响后续业务数据。", "orange"),
        ("下游衔接", "电子合同、订单详情、团队安排总览、导游报账、团队管理列表要与本页按钮保持一致。", "blue"),
    ]
    for i, (title, body, tone) in enumerate(cards):
        x = map_x + i * (card_w + 12)
        rounded(draw, (x, card_y, x + card_w, card_y + 132), 14, "#ffffff", COLORS["line"])
        draw.text((x + 18, card_y + 18), title, font=F16, fill=stat_tone_color(tone))
        draw_text(draw, (x + 18, card_y + 52), body, F12, COLORS["text"], card_w - 36, 3, 5)

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


def draw_team_operation_risk_page(item: dict[str, str], idx: int) -> Path:
    height = 1850
    img, draw = create_canvas_size(W, height)
    draw_tall_shell(draw, item, height)
    draw_page_header(draw, item, idx)

    y = CONTENT_Y + 88
    draw_stat_cards_for_item(draw, CONTENT_X, y, CONTENT_W - 300, item, classify(item))
    y += 100

    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, height - y - 28), "高风险按钮逻辑明细页")
    map_x = CONTENT_X + 22
    map_y = y + 58
    map_w = CONTENT_W - 44
    draw_tall_section_title(draw, map_x, map_y, "1. 高风险按钮必须单独确认", "这些按钮会改变订单归属、人数、团队状态、资源释放或应收应付，不能按普通跳转按钮处理。", map_w)

    card_y = map_y + 82
    card_w = (map_w - 22) // 2
    card_h = 250
    for i, data in enumerate(TEAM_OPERATION_RISK_LOGIC):
        x = map_x + (i % 2) * (card_w + 22)
        yy = card_y + (i // 2) * (card_h + 22)
        if i == 4:
            x = map_x + (map_w - card_w) // 2
        draw_logic_card(draw, x, yy, card_w, card_h, data)

    rule_y = card_y + 3 * (card_h + 22) + 16
    draw_tall_section_title(draw, map_x, rule_y, "2. 统一控制规则", "高风险按钮不只是入口，还要有权限、原因、确认、日志和影响校验。", map_w)
    box_y = rule_y + 74
    rounded(draw, (map_x, box_y, map_x + map_w, box_y + 160), 16, COLORS["red_soft"], COLORS["red"])
    rules = [
        "权限控制：只有主管或管理员能操作。",
        "二次确认：执行前展示影响范围，例如订单、人数、资源、应收应付。",
        "操作留痕：记录操作人、时间、原因和变更前后数据。",
        "状态校验：财务审核、发团、有效订单、资源占用等状态会限制操作。",
    ]
    for i, text in enumerate(rules):
        x = map_x + 28 + (i % 2) * ((map_w - 72) // 2 + 24)
        yy = box_y + 30 + (i // 2) * 54
        draw_text(draw, (x, yy), f"• {text}", F15, COLORS["red"], (map_w - 96) // 2, 2, 5)

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


