def draw_order_rule_card(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, h: int, rule: dict[str, str]):
    tone = rule["tone"]
    color = stat_tone_color(tone)
    bg = COLORS["red_soft"] if tone == "red" else COLORS["orange_soft"] if tone == "orange" else COLORS["blue_soft"]
    rounded(draw, (x, y, x + w, y + h), 15, "#ffffff", COLORS["line"])
    rounded(draw, (x + 14, y + 14, x + w - 14, y + 50), 12, bg)
    draw.text((x + 30, y + 24), rule["title"], font=F16, fill=color)
    yy = y + 66
    for label, key in [("触发条件", "trigger"), ("系统处理", "result"), ("责任角色", "owner"), ("影响页面", "impact")]:
        draw.text((x + 20, yy), label, font=F12, fill=COLORS["muted"])
        yy = draw_text(draw, (x + 88, yy - 1), rule[key], F13, COLORS["text"], w - 110, 2, 4)
        yy += 8


def draw_order_rules_page(item: dict[str, str], idx: int) -> Path:
    height = 2050
    img, draw = create_canvas_size(W, height)
    draw_tall_shell(draw, item, height)
    draw_page_header(draw, item, idx)

    y = CONTENT_Y + 88
    draw_stat_cards_for_item(draw, CONTENT_X, y, CONTENT_W - 300, item, classify(item))
    y += 100

    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, height - y - 28), "下单校验与业务规则提醒")
    map_x = CONTENT_X + 22
    map_y = y + 58
    map_w = CONTENT_W - 44

    draw_tall_section_title(draw, map_x, map_y, "1. 下单不是直接保存", "销售新增或确认订单时，系统先过规则，再决定提醒、转审批、强拦截或生成应收。", map_w)
    flow_y = map_y + 78
    flow_items = [
        ("选择客户/团队", "带出客户主体、授信、合同、团队余位"),
        ("填写订单", "人数、价格、确认件、游客名单"),
        ("规则校验", "额度、主体、合同、收客、名单、资源"),
        ("通过/审批", "通过生成应收；异常转审批或拦截"),
        ("联动下游", "授信占用、团队安排、财务审核、日志"),
    ]
    flow_w = (map_w - 4 * 18) // 5
    for i, (title, desc) in enumerate(flow_items):
        x = map_x + i * (flow_w + 18)
        rounded(draw, (x, flow_y, x + flow_w, flow_y + 116), 14, "#ffffff", COLORS["line"])
        rounded(draw, (x + 16, flow_y + 16, x + 44, flow_y + 44), 14, COLORS["blue_soft"])
        draw.text((x + 25, flow_y + 22), str(i + 1), font=F12, fill=COLORS["blue2"])
        draw_text(draw, (x + 56, flow_y + 18), title, F15, COLORS["text"], flow_w - 72, 1)
        draw_text(draw, (x + 18, flow_y + 62), desc, F12, COLORS["muted"], flow_w - 36, 2, 4)
        if i < len(flow_items) - 1:
            draw_arrow(draw, (x + flow_w + 4, flow_y + 58), (x + flow_w + 16, flow_y + 58), COLORS["blue"], 2)

    rules_y = flow_y + 154
    draw_tall_section_title(draw, map_x, rules_y, "2. 必须补齐的规则", "这些规则和订单、客户、计调、财务都有关，建议作为业务参数和审批预警统一配置。", map_w)
    card_y = rules_y + 78
    card_w = (map_w - 22) // 2
    card_h = 172
    for i, rule in enumerate(ORDER_RULES):
        x = map_x + (i % 2) * (card_w + 22)
        yy = card_y + (i // 2) * (card_h + 20)
        draw_order_rule_card(draw, x, yy, card_w, card_h, rule)

    example_y = card_y + 4 * (card_h + 20) + 14
    draw_tall_section_title(draw, map_x, example_y, "3. 客户额度超限示例", "这是你刚提到的核心场景：客户可用额度不够时，销售在下单/确认订单时必须看到提醒。", map_w)
    box_y = example_y + 76
    rounded(draw, (map_x, box_y, map_x + map_w, box_y + 210), 16, COLORS["red_soft"], COLORS["red"])
    left_w = (map_w - 60) // 2
    draw.text((map_x + 28, box_y + 24), "订单校验弹窗", font=F18, fill=COLORS["red"])
    example_lines = [
        "客户：杭州远行国旅",
        "订单金额：¥86,400",
        "正式授信：¥800,000；已占用：¥760,000；可用额度：¥40,000",
        "本单确认后将超出：¥46,400",
    ]
    yy = box_y + 66
    for line in example_lines:
        draw_text(draw, (map_x + 28, yy), line, F14, COLORS["text"], left_w, 1)
        yy += 30
    right_x = map_x + left_w + 54
    draw.text((right_x, box_y + 24), "系统处理", font=F18, fill=COLORS["red"])
    actions = [
        "提醒销售：客户可用额度不足，不能直接确认订单。",
        "可保存草稿，不生成应收，不占用新的授信。",
        "发起超限审批，财务/主管通过后再确认订单。",
        "审批通过后生成应收、刷新授信占用并保留操作日志。",
    ]
    yy = box_y + 66
    for action in actions:
        draw_text(draw, (right_x, yy), f"• {action}", F14, COLORS["red"], left_w, 2, 4)
        yy += 36

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


