def draw_pt_order_manage_page(item: dict[str, str], idx: int) -> Path:
    height = 1480
    img, draw = create_canvas_size(W, height)
    draw_tall_shell(draw, item, height)
    draw_page_header(draw, item, idx)

    y = CONTENT_Y + 88
    draw_stat_cards_for_item(draw, CONTENT_X, y, CONTENT_W - 300, item, classify(item))
    y += 100

    tabs_h = 356
    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, y + tabs_h), "拼团订单管理")
    top_y = y + 58
    tx = CONTENT_X + 18
    for label, active in [("拼团订单", True), ("拼团操作", False)]:
        fill = COLORS["blue"] if active else "#ffffff"
        text_color = "#ffffff" if active else COLORS["text"]
        rounded(draw, (tx, top_y, tx + 106, top_y + 36), 9, fill, COLORS["line"])
        draw.text((tx + 24, top_y + 11), label, font=F13, fill=text_color)
        tx += 116

    tab_y = top_y + 52
    tx = CONTENT_X + 18
    for label, tone in [("全部", "blue"), ("未拼团", "orange"), ("已拼团", "green"), ("子订单", "orange"), ("按团展示", "blue")]:
        tx = badge(
            draw,
            tx,
            tab_y,
            label,
            stat_tone_color(tone),
            COLORS["blue_soft"] if tone == "blue" else COLORS["green_soft"] if tone == "green" else COLORS["orange_soft"],
            F12,
        )

    status_y = tab_y + 42
    status_h = 114
    rounded(
        draw,
        (CONTENT_X + 18, status_y, CONTENT_X + CONTENT_W - 18, status_y + status_h),
        12,
        "#f7fbff",
        COLORS["line"],
    )
    draw.text((CONTENT_X + 34, status_y + 14), "状态说明", font=F13, fill=COLORS["blue2"])
    status_cards = [
        ("未拼团", "已挂原始团，未建立拼团关系。", "orange"),
        ("已拼团", "已通过拼团操作挂到主执行团。", "green"),
        ("子订单", "已拼团从属订单，跟主执行团执行。", "orange"),
        ("按团展示", "按主执行团查看其下挂订单。", "blue"),
    ]
    card_gap = 12
    status_card_w = int((CONTENT_W - 36 - card_gap * 3) / 4)
    sx = CONTENT_X + 34
    sy = status_y + 40
    for title, desc, tone in status_cards:
        fill = COLORS["blue_soft"] if tone == "blue" else COLORS["green_soft"] if tone == "green" else COLORS["orange_soft"]
        rounded(draw, (sx, sy, sx + status_card_w, sy + 44), 10, fill, COLORS["line"])
        draw.text((sx + 12, sy + 8), title, font=F12, fill=stat_tone_color(tone))
        draw_text(draw, (sx + 12, sy + 24), desc, F10, COLORS["text"], status_card_w - 18, 2, 1)
        sx += status_card_w + card_gap
    draw_text(
        draw,
        (CONTENT_X + 34, status_y + 88),
        "补充说明：订单生成时先挂原始团队；已拼团后原始团不自动删除，后续如需关闭再单独取消或删除团队。",
        F11,
        COLORS["muted"],
        CONTENT_W - 68,
        2,
    )

    filters = [
        ("团号", 120),
        ("预订单位", 140),
        ("出团日期始", 110),
        ("出团日期止", 110),
        ("产品名称", 126),
        ("订单金额", 100),
        ("下单人", 90),
        ("游客名称/证件号", 152),
        ("团队类型", 100),
        ("订单状态", 100),
        ("标记状态", 100),
        ("订单文件", 100),
    ]
    fx = CONTENT_X + 18
    fy = status_y + status_h + 28
    for label, fw in filters:
        if fx + fw > CONTENT_X + CONTENT_W - 112:
            fx = CONTENT_X + 18
            fy += 52
        input_box(draw, fx, fy - 22, fw, label, "全部" if label in {"团队类型", "订单状态", "标记状态", "订单文件"} else "")
        fx += fw + 10
    button(draw, CONTENT_X + CONTENT_W - 96, fy + 8, "搜索", True)

    table_y = y + tabs_h + 18
    table_h = 612
    panel(draw, (CONTENT_X, table_y, CONTENT_X + CONTENT_W, table_y + table_h), "拼团订单清单")
    headers = ["选择", "发团日期", "订单信息", "拼团信息", "接送备注", "客源地", "客人", "人数", "订单", "变更", "已收", "余额", "费用说明", "订单备注", "业务员", "日期/预定人", "状态"]
    ratios = [0.04, 0.08, 0.15, 0.13, 0.09, 0.08, 0.06, 0.05, 0.05, 0.05, 0.05, 0.05, 0.07, 0.06, 0.05, 0.07, 0.04]
    table_x = CONTENT_X + 18
    table_w = CONTENT_W - 36
    header_y = table_y + 54
    rect(draw, (table_x, header_y, table_x + table_w, header_y + 42), COLORS["soft"])
    widths: list[int] = []
    cx = table_x
    for ratio, header in zip(ratios, headers):
        cw = int(table_w * ratio)
        widths.append(cw)
        draw_text(draw, (cx + 5, header_y + 12), header, F9, COLORS["muted"], cw - 8, 2, 1)
        cx += cw

    rows = [
        ["□", "[日]05-18\n散拼", "S04-001\n西湖宋城二日游\n杭州远行国旅", "主执行团：\nHZ20260518-003 西湖宋城二日游", "杭州东接站\nG7561", "浙江杭州", "王小明", "2人", "¥5,400", "¥0", "¥2,000", "¥3,400", "含接送/门票", "需同车", "张伟", "2026/05/10\n张伟", "已确认"],
        ["□", "[一]05-19\n单项", "S04-008\n千岛湖一日游\n上海春秋门店", "-", "千岛湖返程", "上海", "李女士", "4人", "¥6,800", "¥600", "¥0", "¥6,800", "补房差待批", "待拼主团", "张伟", "2026/05/11\n张伟", "待拼团"],
        ["□", "[二]05-20\n单项", "S04-015\n乌镇二日游\n苏州乐游国旅", "主执行团：\nHZ20260522-011 乌镇二日游", "萧山送机", "江苏苏州", "陈先生", "3人", "¥4,600", "¥0", "¥2,000", "¥2,600", "已付定金", "转团到乌镇团", "李娜", "2026/05/12\n李娜", "转团中"],
        ["□", "[三]05-21\n散拼", "S04-019\n华东三日游\n建德欢乐旅行社", "主执行团：\nHZ20260518-003 西湖宋城二日游\n子订单", "城站接站", "浙江建德", "周先生", "5人", "¥9,800", "¥0", "¥4,000", "¥5,800", "代收船票", "共车组A", "陈晨", "2026/05/13\n陈晨", "已确认"],
    ]
    row_y = header_y + 42
    row_h = 108
    for ridx, row in enumerate(rows):
        rect(draw, (table_x, row_y, table_x + table_w, row_y + row_h), "#ffffff" if ridx % 2 == 0 else "#fbfdff")
        draw.line((table_x, row_y + row_h, table_x + table_w, row_y + row_h), fill=COLORS["line2"], width=1)
        cx = table_x
        for i, value in enumerate(row):
            cw = widths[i]
            color = COLORS["green"] if value in {"已确认"} else COLORS["orange"] if value in {"待拼团", "转团中"} else COLORS["red"] if value.startswith("¥-") else COLORS["text"]
            draw_text(draw, (cx + 5, row_y + 10), value, F9, color, cw - 8, 4, 2)
            cx += cw
        row_y += row_h

    draw_text(draw, (table_x, table_y + table_h - 60), "旧系统口径重点：这一页先核对订单、金额、已收和余额，再决定是否执行拼团操作；按团展示时继续看同一团队下挂了哪些订单。", F12, COLORS["muted"], table_w, 2)

    strip_y = table_y + table_h + 18
    panel(draw, (CONTENT_X, strip_y, CONTENT_X + CONTENT_W, strip_y + 130), "业务处理区")
    left_w = 520
    yy = strip_y + 64
    for label, value in [
        ("当前勾选", "S04-001 / S04-019"),
        ("主执行团", "HZ20260518-003 西湖宋城二日游"),
        ("状态判定", "拼团信息有值=已拼团；为空=未拼团"),
        ("按团展示", "查看主执行团下挂了哪些订单"),
    ]:
        draw.text((CONTENT_X + 18, yy), label, font=F12, fill=COLORS["muted"])
        draw_text(draw, (CONTENT_X + 96, yy - 1), value, F13, COLORS["text"], left_w - 120, 2, 2)
        yy += 28

    card_x = CONTENT_X + left_w + 16
    card_w = CONTENT_W - left_w - 34
    card_y = strip_y + 18
    ops = [
        ("切换视图", "在全部、未拼团、已拼团、子订单和按团展示之间切换。", "blue"),
        ("筛选拼团订单", "按团号、预订单位、日期、订单金额、游客和订单状态筛选。", "green"),
        ("拼团处理入口", "勾选订单后进入拼团操作，按团展示用于查看团队归类后的订单关系。", "orange"),
    ]
    for title, desc, tone in ops:
        draw_operation_card(draw, card_x, card_y, card_w, title, desc, tone)
        card_y += 66

    bx = CONTENT_X + CONTENT_W - 330
    bx = button(draw, bx, strip_y + 86, "按团展示", False)
    bx = button(draw, bx, strip_y + 86, "转团", False)
    button(draw, bx, strip_y + 86, "拼团操作", True)

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


def draw_ticket_template_center_page(item: dict[str, str], idx: int) -> Path:
    height = 1420
    img, draw = create_canvas_size(W, height)
    draw_tall_shell(draw, item, height)
    draw_page_header(draw, item, idx)

    y = CONTENT_Y + 88

    top_h = 170
    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, y + top_h), "票务模板生成中心")
    note_x = CONTENT_X + 18
    note_y = y + 60
    draw_text(
        draw,
        (note_x, note_y),
        "核心价值：同一团队去不同景区时，系统可按景区自动匹配不同票务系统和不同 Excel 模板，直接带入团队游客名单生成下单文件；接口下单保留为次入口。",
        F14,
        COLORS["text"],
        CONTENT_W - 260,
        3,
        5,
    )
    badge(draw, note_x, y + 116, "多票务系统", COLORS["blue2"], COLORS["blue_soft"], F12)
    bx = badge(draw, note_x + 112, y + 116, "多套Excel模板", COLORS["green"], COLORS["green_soft"], F12)
    bx = badge(draw, bx, y + 116, "团队游客名单自动带入", COLORS["orange"], COLORS["orange_soft"], F12)
    button(draw, CONTENT_X + CONTENT_W - 276, y + 70, "生成Excel", True)
    button(draw, CONTENT_X + CONTENT_W - 170, y + 70, "导出Excel", False)
    button(draw, CONTENT_X + CONTENT_W - 82, y + 70, "接口下单", False)

    filter_y = y + top_h + 18
    panel(draw, (CONTENT_X, filter_y, CONTENT_X + CONTENT_W, filter_y + 120), "查询条件")
    fx = CONTENT_X + 18
    fy = filter_y + 62
    filter_specs = [
        ("团队", 190, CASE["team"]),
        ("景区", 170, "全部"),
        ("使用日期", 140, "2026-05-18"),
        ("票务系统", 140, "全部"),
        ("模板状态", 140, "全部"),
        ("预约状态", 140, "全部"),
    ]
    for label, fw, value in filter_specs:
        input_box(draw, fx, fy - 24, fw, label, value)
        fx += fw + 12
    button(draw, CONTENT_X + CONTENT_W - 92, fy + 8, "查询", True)

    main_y = filter_y + 138
    left_w = 980
    panel(draw, (CONTENT_X, main_y, CONTENT_X + left_w, main_y + 500), "团队门票任务")
    headers = ["团队/景区", "票种/人数", "票务系统", "模板版本", "游客名单来源", "Excel生成状态", "下单方式", "预约状态", "成本归属"]
    ratios = [0.18, 0.13, 0.11, 0.10, 0.12, 0.11, 0.09, 0.08, 0.08]
    tx = CONTENT_X + 18
    tw = left_w - 36
    hy = main_y + 54
    rect(draw, (tx, hy, tx + tw, hy + 40), COLORS["soft"])
    widths: list[int] = []
    cx = tx
    for header, ratio in zip(headers, ratios):
        cw = int(tw * ratio)
        widths.append(cw)
        draw_text(draw, (cx + 6, hy + 11), header, F9, COLORS["muted"], cw - 10, 2, 1)
        cx += cw

    rows = [
        [CASE["team"] + "\n苏州园林", "成人28/儿童4/老人2", "票务系统A", "模板A v3", "团队游客名单自动带入", "已生成Excel", "导出Excel", "待上传", "订单S04-001"],
        [CASE["team"] + "\n南京紫金山", "成人18/儿童2", "票务系统B", "模板B v2", "团队游客名单自动带入", "已生成Excel", "接口下单", "已预约", "团队成本"],
        ["HZ20260522-011\n小众景区", "成人12/儿童1", "无接口模板", "通用票务表", "团队游客名单自动带入", "待生成", "导出Excel", "人工上传中", "订单S04-015"],
    ]
    ry = hy + 40
    row_h = 118
    for ridx, row in enumerate(rows):
        rect(draw, (tx, ry, tx + tw, ry + row_h), "#ffffff" if ridx % 2 == 0 else "#fbfdff")
        draw.line((tx, ry + row_h, tx + tw, ry + row_h), fill=COLORS["line2"], width=1)
        cx = tx
        for i, value in enumerate(row):
            color = COLORS["green"] if value in {"已预约"} else COLORS["orange"] if value in {"待上传", "人工上传中", "待生成"} else COLORS["text"]
            draw_text(draw, (cx + 6, ry + 10), value, F9 if i >= 2 else F10, color, widths[i] - 10, 4, 2)
            cx += widths[i]
        ry += row_h

    button(draw, CONTENT_X + 18, main_y + 522, "查看模板", False)
    bx = button(draw, CONTENT_X + 108, main_y + 522, "生成Excel", True)
    bx = button(draw, bx, main_y + 522, "导出Excel", False)
    button(draw, bx, main_y + 522, "接口下单", False)

    right_x = CONTENT_X + left_w + 18
    right_w = CONTENT_W - left_w - 18
    panel(draw, (right_x, main_y, right_x + right_w, main_y + 500), "当前任务处理")
    info_y = main_y + 62
    details = [
        ("当前任务", CASE["team"] + " / 苏州园林"),
        ("票务系统", "票务系统A"),
        ("模板版本", "模板A v3"),
        ("下单方式", "导出Excel为主，接口下单为次入口"),
        ("游客名单", "团队游客名单自动带入"),
        ("状态", "已生成Excel / 待上传"),
    ]
    for label, value in details:
        draw.text((right_x + 18, info_y), label, font=F12, fill=COLORS["muted"])
        draw_text(draw, (right_x + 94, info_y - 1), value, F13, COLORS["text"], right_w - 112, 2, 2)
        info_y += 30

    chain_y = info_y + 12
    chain_cards = [
        ("团队游客名单", "从团队名单自动取成人/儿童/老人信息。", "blue"),
        ("自动匹配票务系统/模板", "按景区自动识别票务系统A/票务系统B和模板版本。", "green"),
        ("生成Excel", "生成对应Excel模板，少量特殊字段人工补充。", "orange"),
        ("导出下单 / 接口下单", "优先导出Excel；有接口条件的票务系统可直接提交。", "blue"),
        ("预约结果回写", "回写预约状态、失败原因和票务凭证。", "green"),
        ("票务成本回写", "成功后回写订单或团队成本。", "orange"),
    ]
    cy = chain_y
    for title, desc, tone in chain_cards:
        draw_operation_card(draw, right_x + 18, cy, right_w - 36, title, desc, tone)
        cy += 56

    diff_y = main_y + 518
    panel(draw, (CONTENT_X, diff_y, CONTENT_X + CONTENT_W, diff_y + 246), "模板差异示意")
    section_w = (CONTENT_W - 54) // 3
    template_sections = [
        ("苏州园林 -> 票务系统A -> 模板A", "字段：姓名/证件号/票种/手机号", ["团队游客名单自动带入", "成人/儿童/老人自动汇总", "需补：游玩场次"], "blue"),
        ("南京紫金山 -> 票务系统B -> 模板B", "字段：姓名/证件号/出生日期/联系人", ["团队游客名单自动带入", "票种和人数自动映射", "需补：预约时间段"], "green"),
        ("无接口景区 -> 导出Excel后人工上传", "字段：通用游客模板/手工补票价", ["团队游客名单自动带入", "生成通用票务表", "人工上传后回写结果"], "orange"),
    ]
    sx = CONTENT_X + 18
    for title, subtitle, lines, tone in template_sections:
        fill = COLORS["blue_soft"] if tone == "blue" else COLORS["green_soft"] if tone == "green" else COLORS["orange_soft"]
        rounded(draw, (sx, diff_y + 60, sx + section_w, diff_y + 210), 14, "#ffffff", COLORS["line"])
        rounded(draw, (sx, diff_y + 60, sx + section_w, diff_y + 96), 14, fill, COLORS["line"])
        draw_text(draw, (sx + 12, diff_y + 70), title, F12, stat_tone_color(tone), section_w - 24, 2, 1)
        draw_text(draw, (sx + 12, diff_y + 106), subtitle, F11, COLORS["text"], section_w - 24, 2, 2)
        ly = diff_y + 138
        for line in lines:
            draw_text(draw, (sx + 18, ly), "· " + line, F10, COLORS["muted"], section_w - 30, 2, 1)
            ly += 22
        sx += section_w + 9

    draw_operation_strip(draw, CONTENT_X, diff_y + 264, CONTENT_W, item, classify(item))

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


def draw_group_manage_page(item: dict[str, str], idx: int) -> Path:
    img, draw = create_canvas()
    draw_shell(draw, item)
    draw_page_header(draw, item, idx)

    y = CONTENT_Y + 88
    draw_stat_cards_for_item(draw, CONTENT_X, y, CONTENT_W - 300, item, classify(item))
    y += 100

    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, y + 708), "团队/团期管理")
    panel_x = CONTENT_X + 18
    panel_y = y + 56
    panel_w = CONTENT_W - 36

    tab_x = panel_x
    for tab in ["全部", "散拼", "整团", "散团", "单项"]:
        active = tab == "全部"
        tw = 86
        fill = COLORS["blue"] if active else "#ffffff"
        color = "#ffffff" if active else COLORS["text"]
        rounded(draw, (tab_x, panel_y, tab_x + tw, panel_y + 44), 9, fill, COLORS["line"])
        draw.text((tab_x + 26, panel_y + 14), tab, font=F14, fill=color)
        tab_x += tw + 10

    action_x = CONTENT_X + CONTENT_W - 472
    for label in ["新增散拼", "新增整团", "新增散团", "新增单项"]:
        rounded(draw, (action_x, panel_y + 5, action_x + 104, panel_y + 41), 8, COLORS["blue"], COLORS["blue"])
        draw.text((action_x + 20, panel_y + 16), label, font=F12, fill="#ffffff")
        action_x += 112

    filter_y = panel_y + 68
    filter_fields = [
        ("团号/团队名称/备注", 180),
        ("客户单位/业务员", 150),
        ("导游", 92),
        ("操作计调", 106),
        ("出发地", 96),
        ("部门", 104),
        ("业务类型", 112),
        ("订单状态", 112),
        ("出团日期", 126),
        ("添加日期", 126),
        ("天数", 70),
        ("全部团队", 110),
    ]
    fx = panel_x
    fy = filter_y
    for label, fw in filter_fields:
        if fx + fw > panel_x + panel_w - 120:
            fx = panel_x
            fy += 52
        input_box(draw, fx, fy - 20, fw, label, "全部" if label in {"部门", "业务类型", "订单状态", "全部团队"} else "")
        fx += fw + 10
    button(draw, panel_x + panel_w - 96, fy + 10, "搜索", True)

    table_y = filter_y + 104
    table_x = panel_x
    table_w = panel_w
    table_h = 300
    panel(draw, (table_x, table_y, table_x + table_w, table_y + table_h), "团队列表")
    header_y = table_y + 52
    columns = [
        ("类型", 52),
        ("团号", 126),
        ("客户", 96),
        ("团队名称", 250),
        ("天数", 44),
        ("开始", 58),
        ("结束", 58),
        ("出发地", 62),
        ("预控/实收", 92),
        ("导游信息", 118),
    ]
    status_cols = list("导交住车景餐其自购地进")
    fixed_w = sum(w for _, w in columns)
    status_w = max(26, (table_w - 36 - fixed_w) // len(status_cols))
    rect(draw, (table_x + 18, header_y, table_x + table_w - 18, header_y + 42), COLORS["soft"])
    cx = table_x + 18
    for header, cw in columns:
        draw_text(draw, (cx + 6, header_y + 13), header, F11, COLORS["muted"], cw - 10, 1)
        cx += cw
    for header in status_cols:
        draw_text(draw, (cx + 8, header_y + 13), header, F11, COLORS["muted"], status_w - 8, 1)
        cx += status_w

    rows = [
        ["整团", "CS-CS-261201A", "易游国旅", "度假村2晚+万豪国四2晚 安排越野车", "5天", "12/01", "12/05", "新加坡", "8人 [8/0/0]", "liuweif-女 13819202641", ["done", "pending", "pending", "pending", "pending", "pending", "none", "done", "none", "pending", "done"]],
        ["散拼", "CS-SP-CS-260710B", "--", "SINB-D2M2经典B版新加坡一地5D4N(2+2)", "5天", "07/10", "07/14", "新加坡", "31人 [0/0/0]", "赵欣-男 18947553622", ["done", "none", "pending", "pending", "pending", "pending", "none", "none", "none", "none", "done"]],
        ["散拼", "CS-SP-CS-260708A", "之江饭店工会", "SINB-D2M2经典B版新加坡一地5D4N(2+2)", "5天", "07/08", "07/12", "新加坡", "31人 [11/7/0]", "周辉辉-男 18867532829", ["done", "none", "pending", "pending", "pending", "pending", "none", "pending", "none", "none", "none"]],
    ]
    row_y = header_y + 48
    row_h = 50
    for ridx, row in enumerate(rows):
        rect(draw, (table_x + 18, row_y, table_x + table_w - 18, row_y + row_h), "#ffffff" if ridx % 2 == 0 else "#fbfdff")
        draw.line((table_x + 18, row_y + row_h, table_x + table_w - 18, row_y + row_h), fill=COLORS["line2"], width=1)
        cx = table_x + 18
        values = row[:10]
        statuses = row[10]
        for i, value in enumerate(values):
            cw = columns[i][1]
            color = COLORS["blue2"] if i in {1, 3, 9} else COLORS["orange"] if i == 0 and value in {"散拼", "散团"} else COLORS["text"]
            font = F11 if i in {2, 3, 9} else F12
            draw_text(draw, (cx + 6, row_y + 13), value, font, color, cw - 10, 2)
            cx += cw
        for status in statuses:
            draw_status_dot(draw, cx + 4, row_y + 17, status)
            cx += status_w
        row_y += row_h

    legend_y = table_y + table_h - 42
    draw_status_dot(draw, table_x + 24, legend_y, "done")
    draw.text((table_x + 50, legend_y + 2), "已完成", font=F12, fill=COLORS["muted"])
    draw_status_dot(draw, table_x + 116, legend_y, "pending")
    draw.text((table_x + 142, legend_y + 2), "待处理", font=F12, fill=COLORS["muted"])
    draw_status_dot(draw, table_x + 208, legend_y, "none")
    draw.text((table_x + 236, legend_y + 2), "无此项", font=F12, fill=COLORS["muted"])
    draw_text(draw, (table_x + 330, legend_y), "资源列：导=导游、交=交通、住=住宿、车=用车、景=景区、餐=用餐、其=其它、自=自费、购=购物、地=地接、进=进度/审核。", F12, COLORS["muted"], table_w - 360, 1)

    draw_resource_operation_panel(draw, table_x, table_y + table_h + 10, table_w, 160)

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


