    draw_text(draw, (CONTENT_X + 34, explain_y + 14), "入口说明：点击住进入酒店房态页，查看酒店主档、日期房态并完成排房房调；点击车进入派车页，查看车辆资源与日期占用后完成询价、比价和派车。这里先看团队有没有房、有没有车、哪些团还没落实。", F12, COLORS["orange"], main_w - 68, 3)

    draw_operation_strip(draw, CONTENT_X, y + 548, main_w, item, classify(item))

    drawer_x = CONTENT_X + main_w + 18
