    ty = y + 56
    for label in ["订单文件", "打印团队名单", "票据库", "现付销账", "返佣现结", "打印请款单", "打印报账单", "预算毛利表", "打印毛利表", "打印结算单", "购物明细"]:
        tx = badge(draw, tx, ty, label, COLORS["blue2"], COLORS["blue_soft"], F10)
        if tx > CONTENT_X + CONTENT_W - 110:
            tx = CONTENT_X + 18
            ty += 28
    meta_y = y + 112
    financial_meta = [
        ("团队", CASE["team"]),
        ("客户", CASE["customer"]),
        ("应收/已收/余额", "¥86,400 / ¥20,000 / ¥66,400"),
        ("已付", "¥31,200"),
        ("审核链路", "团队安排 -> 导游报账 -> 计调审核 -> 财务审核"),
        ("审核状态", "待财务审核"),
    ]
    for i, (label, value) in enumerate(financial_meta):
        xx = CONTENT_X + 18 + (i % 3) * 392
        yy = meta_y + (i // 3) * 30
        draw.text((xx, yy), label, font=F11, fill=COLORS["muted"])
        draw_text(draw, (xx + 104, yy - 1), value, F12, COLORS["text"], 282, 1)

    sum_y = y + header_h + 18
    panel(draw, (CONTENT_X, sum_y, CONTENT_X + CONTENT_W, sum_y + 106), "审核金额概况")
    summary = [
        ("应收", "¥86,400", "green"),
        ("已收", "¥20,000", "blue"),
        ("余额", "¥66,400", "warning"),
        ("应付", "¥52,800", "blue"),
        ("已付", "¥31,200", "orange"),
        ("结算利润", "¥28,600", "warning"),
    ]
    card_w = (CONTENT_W - 18 - 5 * 12) // 6
    for i, (label, value, tone) in enumerate(summary):
        xx = CONTENT_X + 18 + i * (card_w + 12)
        rounded(draw, (xx, sum_y + 18, xx + card_w, sum_y + 84), 12, "#ffffff", COLORS["line"])
        draw.text((xx + 12, sum_y + 30), label, font=F11, fill=COLORS["muted"])
        draw.text((xx + 12, sum_y + 54), value, font=F16, fill=stat_tone_color(tone))

    left_w = 940
    detail_y = sum_y + 122
    panel(draw, (CONTENT_X, detail_y, CONTENT_X + left_w, detail_y + 336), "资源成本与财务审核")
    headers = ["资源/项目", "收入/成本来源", "现结/挂账", "导游报账", "购物/返佣", "审核列"]
    ratios = [0.16, 0.24, 0.14, 0.14, 0.14, 0.18]
    tx = CONTENT_X + 18
    tw = left_w - 36
    hy = detail_y + 52
    rect(draw, (tx, hy, tx + tw, hy + 36), COLORS["soft"])
    widths: list[int] = []
    cx = tx
    for header, ratio in zip(headers, ratios):
        cw = int(tw * ratio)
        widths.append(cw)
        draw_text(draw, (cx + 6, hy + 10), header, F10, COLORS["muted"], cw - 10, 2, 1)
        cx += cw
    rows = [
        ["订单收入", "订单+费用变更", "-", "-", "-", "已核应收"],
        ["住宿", "湖滨酒店成本", "挂账 ¥18,400", "-", "-", "缺发票"],
        ["用车", "西湖车队成本", "现结 ¥4,800", "待销账", "-", "待复核"],
        ["购物返佣", "购物点返佣", "-", "-", "返佣 ¥1,800", "待现结"],
        ["导游相关", "导服/备用金/操作费", "现结 ¥3,200", "凭证2份", "-", "待复审"],
    ]
    ry = hy + 36
    for ridx, row in enumerate(rows):
        row_h = 52
        rect(draw, (tx, ry, tx + tw, ry + row_h), "#ffffff" if ridx % 2 == 0 else "#fbfdff")
        draw.line((tx, ry + row_h, tx + tw, ry + row_h), fill=COLORS["line2"], width=1)
        cx = tx
        for i, value in enumerate(row):
            color = COLORS["orange"] if value in {"缺发票", "待复核", "待现结", "待复审"} else COLORS["green"] if value == "已核应收" else COLORS["text"]
            draw_text(draw, (cx + 6, ry + 16), value, F10, color, widths[i] - 10, 2, 2)
            cx += widths[i]
        ry += row_h

    right_x = CONTENT_X + left_w + 18
    right_w = CONTENT_W - left_w - 18
    panel(draw, (right_x, detail_y, right_x + right_w, detail_y + 336), "财务处理区")
    yy = detail_y + 64
    info = [
        ("当前项", "住宿 / 湖滨酒店"),
        ("审核链路", "承接计调审核后的财务终审"),
        ("应收余额", "¥66,400"),
        ("已付/余款", "¥12,000 / ¥6,400"),
        ("购物返佣", "¥1,800 待现结"),
        ("锁定规则", "审核通过后锁定结算口径"),
    ]
    for label, value in info:
        draw.text((right_x + 18, yy), label, font=F11, fill=COLORS["muted"])
        draw_text(draw, (right_x + 96, yy - 1), value, F12, COLORS["text"], right_w - 114, 2, 2)
        yy += 30
    draw.line((right_x + 18, yy + 4, right_x + right_w - 18, yy + 4), fill=COLORS["line"], width=1)
    yy += 22
    cards = [
        ("承接计调审核", "沿用同一团队信息和金额口径，接着核财务结算。", "blue"),
        ("财务审核", "异常项退回补充，已付、余款、发票和现付销账一起核。", "orange"),
        ("锁定结算口径", "审核通过后限制修改费用、成本和利润关键口径。", "green"),
    ]
    for title, desc, tone in cards:
        draw_operation_card(draw, right_x + 18, yy, right_w - 36, title, desc, tone)
        yy += 66
    button(draw, right_x + 18, detail_y + 288, "审核通过", True)
    button(draw, right_x + 126, detail_y + 288, "退回补充", False)

    strip_y = detail_y + 354
    draw_operation_strip(draw, CONTENT_X, strip_y, CONTENT_W, item, classify(item))

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


