        cx = tx
        for i, (value, cw) in enumerate(zip(row, widths)):
            color = COLORS["orange"] if value in {"待销账", "待审批", "待付款", "未销账"} else COLORS["green"] if value in {"已付款", "已完成", "已销账", "部分销账"} else COLORS["text"]
            draw_text(draw, (cx + 6, ry + 14), value, F10, color, cw - 10, 3, 2)
