    draw_text(draw, (CONTENT_X + 18, y + 364), "预付款只表达供应商/资源预付，不替代导游备用金。后续随着资源成本确认做预付款销账，持续跟踪已付金额、余款和差异。", F12, COLORS["text"], left_w - 36, 2)

