def draw_guide_wechat_mini_program_page(item: dict[str, str], idx: int) -> Path:
    width, height = 1600, 2400
    img, draw = create_canvas_size(width, height)
    rounded(draw, (36, 36, width - 36, height - 36), 30, "#ffffff", COLORS["line"])

    draw.text((72, 72), f"{item['模块']} / {client_title(item)}", font=F30, fill=COLORS["text"])
    draw_text(draw, (72, 118), "这张是正式导游角色端页面，专门给客户看导游登录微信小程序后有哪些菜单、怎么看团队、怎么报账核销、退回后怎么补报，以及结果最终回写到哪里。", F15, COLORS["muted"], width - 144, 2, 4)
    tx = 72
    for label, tone in [("微信小程序", "blue"), ("导游角色端", "green"), ("提交/补报/查看", "orange"), ("后台审核回写", "red")]:
        if tone == "green":
            tx = badge(draw, tx, 162, label, COLORS["green"], COLORS["green_soft"], F11)
        elif tone == "orange":
            tx = badge(draw, tx, 162, label, COLORS["orange"], COLORS["orange_soft"], F11)
        elif tone == "red":
            tx = badge(draw, tx, 162, label, COLORS["red"], COLORS["red_soft"], F11)
        else:
            tx = badge(draw, tx, 162, label, COLORS["blue2"], COLORS["blue_soft"], F11)

    def tone_fill(tone: str) -> tuple[str, str]:
        if tone == "green":
            return COLORS["green"], COLORS["green_soft"]
        if tone == "orange":
            return COLORS["orange"], COLORS["orange_soft"]
        if tone == "red":
            return COLORS["red"], COLORS["red_soft"]
        return COLORS["blue2"], COLORS["blue_soft"]

    def mini_tile(x: int, y: int, w: int, h: int, title: str, value: str, tone: str = "blue"):
        color, fill = tone_fill(tone)
        rounded(draw, (x, y, x + w, y + h), 16, fill, COLORS["line"])
        draw_text(draw, (x + 14, y + 12), title, F13, color, w - 28, 1, 2)
        draw_text(draw, (x + 14, y + 38), value, F11, COLORS["text"], w - 28, 2, 3)

    def small_kv(x: int, y: int, label: str, value: str, w: int, tone: str = "blue") -> int:
        color, fill = tone_fill(tone)
        rounded(draw, (x, y, x + w, y + 44), 12, fill, COLORS["line"])
        draw_text(draw, (x + 12, y + 8), label, F11, color, 88, 1, 2)
        draw_text(draw, (x + 104, y + 8), value, F12, COLORS["text"], w - 116, 1, 2)
        return y + 54

    def list_row(x: int, y: int, w: int, title: str, meta: str, status: str, tone: str):
        color, fill = tone_fill(tone)
        rounded(draw, (x, y, x + w, y + 70), 14, "#ffffff", COLORS["line"])
        rounded(draw, (x + 12, y + 14, x + 94, y + 42), 12, fill, fill)
