    draw_mobile_feature_card(draw, 96, note_y + 182, 674, 76, "和导游端的关系", "最后一页导游端讲手机上怎么报账和核销；本页只讲财务如何审批、付款、复审和完成退补。", "blue")
    draw_mobile_feature_card(draw, 792, note_y + 182, 678, 76, "和团队预付款的关系", "导游备用金继续单独表达，不替代团队预付款；供应商/资源预付仍回团队预付款页。", "green")

