def draw_tabs_row(draw: ImageDraw.ImageDraw, x: int, y: int, labels: list[str], active: int = 0, tone: str = "blue", max_width: int | None = None) -> int:
    tx = x
    current_y = y
    active_fill = COLORS["blue"] if tone == "blue" else COLORS["green"] if tone == "green" else COLORS["orange"]
    active_text = "#ffffff"
    soft_fill = COLORS["blue_soft"] if tone == "blue" else COLORS["green_soft"] if tone == "green" else COLORS["orange_soft"]
    for idx, label in enumerate(labels):
        tw, _ = text_size(draw, label, F12)
        w = tw + 26
        if max_width and tx + w > max_width:
            tx = x
            current_y += 34
        fill = active_fill if idx == active else "#ffffff"
        outline = active_fill if idx == active else COLORS["line"]
        color = active_text if idx == active else COLORS["text"]
        if idx != active:
            fill = soft_fill if idx == active else "#ffffff"
        rounded(draw, (tx, current_y, tx + w, current_y + 28), 14, fill, outline)
        draw.text((tx + 13, current_y + 8), label, font=F12, fill=color)
        tx += w + 8
    return current_y


def draw_checkbox_item(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, text: str, checked: bool = True):
    rounded(draw, (x, y, x + w, y + 34), 10, "#ffffff", COLORS["line"])
    rect(draw, (x + 12, y + 8, x + 30, y + 26), COLORS["blue"] if checked else "#ffffff", COLORS["blue"] if checked else COLORS["line"])
    if checked:
        draw.text((x + 16, y + 8), "✓", font=F11, fill="#ffffff")
    draw_text(draw, (x + 40, y + 10), text, F11, COLORS["text"], w - 54, 2, 2)


