    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, y + 474), "导游排班月历")
    cal_x = CONTENT_X + 18
    cal_y = y + 56
    left_w = 136
    day_w = (CONTENT_W - 36 - left_w) // 7
    row_h = 82
    days = ["05.15[五]", "05.16[六]", "05.17[日]", "05.18[一]", "05.19[二]", "05.20[三]", "05.21[四]"]
    rect(draw, (cal_x, cal_y, cal_x + left_w + day_w * 7, cal_y + 42), COLORS["soft"])
    draw.text((cal_x + 12, cal_y + 13), "导游", font=F12, fill=COLORS["muted"])
    for i, day in enumerate(days):
        draw_text(draw, (cal_x + left_w + i * day_w + 8, cal_y + 13), day, F11, COLORS["muted"], day_w - 10, 2, 1)

    guides = [
        ("导游1", [("", "empty"), ("00:00上团\nCS-DW-CS-260605A\n23:59下团", "busy"), ("", "empty"), ("", "empty"), ("", "empty"), ("", "empty"), ("", "empty")]),
        (CASE["guide"], [("", "empty"), ("", "empty"), ("08:00上团\n" + CASE["team"][:18], "busy"), ("延续占用\n23:59下团", "busy"), ("待报账", "pending"), ("", "empty"), ("", "empty")]),
        ("李娜", [("", "empty"), ("", "empty"), ("同日冲突\nHZ20260520-006", "conflict"), ("", "empty"), ("", "empty"), ("", "empty"), ("", "empty")]),
        ("王强", [("", "empty"), ("", "empty"), ("", "empty"), ("", "empty"), ("上团\nHZ20260522-011", "busy"), ("下团", "busy"), ("已报账", "done")]),
    ]
    fills = {"empty": "#ffffff", "busy": COLORS["blue_soft"], "pending": COLORS["orange_soft"], "conflict": COLORS["red_soft"], "done": COLORS["green_soft"]}
    colors = {"empty": COLORS["muted"], "busy": COLORS["blue2"], "pending": COLORS["orange"], "conflict": COLORS["red"], "done": COLORS["green"]}
    for ridx, (guide, cells) in enumerate(guides):
        ry = cal_y + 42 + ridx * row_h
        rect(draw, (cal_x, ry, cal_x + left_w + day_w * 7, ry + row_h), "#ffffff" if ridx % 2 == 0 else "#fbfdff")
        draw.line((cal_x, ry + row_h, cal_x + left_w + day_w * 7, ry + row_h), fill=COLORS["line2"], width=1)
        draw_text(draw, (cal_x + 12, ry + 28), guide, F13, COLORS["text"], left_w - 20, 1)
        for i, (text, tone) in enumerate(cells):
            cx = cal_x + left_w + i * day_w + 6
            rounded(draw, (cx, ry + 10, cx + day_w - 12, ry + row_h - 10), 10, fills[tone], COLORS["line"])
            if text:
                draw_text(draw, (cx + 8, ry + 18), text, F10, colors[tone], day_w - 28, 3, 2)
            elif tone == "empty":
                draw.text((cx + 18, ry + 28), "-", font=F12, fill=COLORS["muted"])

    legend_y = y + 398
    lx = cal_x
    for label, tone in [("已占用", "busy"), ("待报账", "pending"), ("冲突", "conflict"), ("已报账", "done")]:
        rounded(draw, (lx, legend_y, lx + 92, legend_y + 28), 14, fills[tone])
        draw.text((lx + 14, legend_y + 8), label, font=F11, fill=colors[tone])
        lx += 104
    draw_text(draw, (cal_x, legend_y + 42), "月历按导游行、日期列展示；冲突用于提醒重复排班，修改派团要回到导游安排页处理。", F12, COLORS["text"], CONTENT_W - 36, 2)

    draw_operation_strip(draw, CONTENT_X, y + 492, CONTENT_W, item, classify(item))

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


