def draw_tabbed_stats_page(item: dict[str, str], idx: int) -> Path:
    config = {
        "BI02": {"tabs": ["按客户统计", "按区域统计", "按业务员", "按操作计调", "按收客计调", "按站点统计", "按产品统计"], "button": "导出报表", "chart": "bar"},
        "BI03": {"tabs": ["年度总览", "总览", "按团队", "按订单", "按导游", "按操作计调", "按收客计调", "按业务员", "按客户", "按产品"], "button": "刷新利润统计数据", "chart": "line"},
        "BI08": {"tabs": ["应收账款", "应付账款", "收款统计", "付款统计", "业务员应收账款", "收客计调应收账款"], "button": "导出报表", "chart": "stack"},
        "BI09": {"tabs": ["总览", "带团统计", "购物统计", "自费统计", "杂费统计"], "button": "刷新统计人数", "chart": "bar"},
    }[item["编号"]]
    img, draw = create_canvas()
    draw_shell(draw, item)
    draw_page_header(draw, item, idx)

    y = CONTENT_Y + 88
    draw_stat_cards_for_item(draw, CONTENT_X, y, CONTENT_W - 300, item, classify(item))
    y += 100

    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, y + 144), raw_title(item))
    draw_tabs_row(draw, CONTENT_X + 18, y + 18, config["tabs"], 0, "blue", CONTENT_X + CONTENT_W - 140)
    button(draw, CONTENT_X + CONTENT_W - 132, y + 18, config["button"], False)
    filter_labels = {
        "BI02": [("开始日期", 120), ("结束日期", 120), ("业务类型", 120), ("统计口径", 120)],
        "BI03": [("开始日期", 120), ("结束日期", 120), ("部门", 120), ("业务类型", 120)],
        "BI08": [("开始日期", 120), ("结束日期", 120), ("账款口径", 150), ("风险等级", 120)],
        "BI09": [("开始日期", 120), ("结束日期", 120), ("导游", 120), ("统计口径", 120)],
    }[item["编号"]]
    fx = CONTENT_X + 18
    fy = y + 78
    for label, fw in filter_labels:
        input_box(draw, fx, fy - 20, fw, label, "")
        fx += fw + 10
    button(draw, fx + 10, fy + 8, "统计", True if item["编号"] == "BI02" else False)
    if item["编号"] != "BI02":
        button(draw, fx + 100, fy + 8, "搜索", True)

    content_y = y + 162
    left_w = 760
    panel(draw, (CONTENT_X, content_y, CONTENT_X + left_w, content_y + 252), "统计图")
    chart_x = CONTENT_X + 36
    chart_y = content_y + 58
    base_y = content_y + 218
    draw.line((chart_x, chart_y, chart_x, base_y), fill=COLORS["line"], width=1)
    draw.line((chart_x, base_y, CONTENT_X + left_w - 28, base_y), fill=COLORS["line"], width=1)
    if config["chart"] == "line":
        pts = [(chart_x + 30, base_y - 40), (chart_x + 160, base_y - 58), (chart_x + 290, base_y - 70), (chart_x + 420, base_y - 92), (chart_x + 550, base_y - 110)]
        for a, b in zip(pts, pts[1:]):
            draw.line((a[0], a[1], b[0], b[1]), fill=COLORS["blue"], width=4)
        for px, py in pts:
            draw.ellipse((px - 5, py - 5, px + 5, py + 5), fill=COLORS["blue"])
    else:
        vals = [110, 86, 72, 58, 42]
        labels = ["A", "B", "C", "D", "E"]
        bar_w = 72
        for i, val in enumerate(vals):
            xx = chart_x + 34 + i * 118
            rect(draw, (xx, base_y - val, xx + bar_w, base_y), COLORS["blue_soft"], COLORS["blue"])
            draw.text((xx + 18, base_y - val - 22), str(val), font=F12, fill=COLORS["blue2"])
            draw.text((xx + 26, base_y + 8), labels[i], font=F11, fill=COLORS["muted"])

    right_x = CONTENT_X + left_w + 18
    right_w = CONTENT_W - left_w - 18
    panel(draw, (right_x, content_y, right_x + right_w, content_y + 252), "统计口径说明")
    notes = {
        "BI02": ["有效人数与收客人数并列看，避免绩效口径失真。", "切换客户、区域、业务员、产品等统计口径。", "成人、儿童、免票和特殊票种都要纳入说明。", "导出后用于销售复盘和绩效核算。"] ,
        "BI03": ["利润来自订单收入、费用变更、资源成本和返佣。", "先刷新利润统计数据，再按团队/订单/客户等口径看。", "支持快速识别低利润或异常团队。", "下钻后回到订单或团队成本明细。"] ,
        "BI08": ["同一页切换应收、应付、收款、付款等账款口径。", "重点看账龄、授信占用和高风险客户。", "收款统计与付款统计也从这页切换。", "适合老板和财务关注回款与付款压力。"] ,
        "BI09": ["按导游看带团、购物、自费和杂费表现。", "刷新统计人数后再导出结果。", "和导游排班、报账、结算联动。", "支持导游绩效和服务复盘。"] ,
    }[item["编号"]]
    yy = content_y + 58
    for note in notes:
        draw_text(draw, (right_x + 18, yy), f"• {note}", F12, COLORS["text"], right_w - 36, 2, 4)
        yy += 50

    table_y = content_y + 270
    draw_table(draw, CONTENT_X, table_y, CONTENT_W, 248, item, classify(item))

    draw_operation_strip(draw, CONTENT_X, table_y + 266, CONTENT_W, item, classify(item))

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


def draw_sys_config_form_page(item: dict[str, str], idx: int) -> Path:
    img, draw = create_canvas()
    draw_shell(draw, item)
    draw_page_header(draw, item, idx)

    y = CONTENT_Y + 88
    draw_stat_cards_for_item(draw, CONTENT_X, y, CONTENT_W - 300, item, classify(item))
    y += 100

    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, y + 610), "参数设置")
    button(draw, CONTENT_X + CONTENT_W - 132, y + 18, "提交保存", True)
    input_box(draw, CONTENT_X + 18, y + 18, 150, "出团日期", "2026-05-18")
    input_box(draw, CONTENT_X + 188, y + 18, 150, "设置日期", "2026-05-15")
    draw_text(draw, (CONTENT_X + 364, y + 28), "这页直接控制系统行为，不是普通参数表。勾选后会影响导游报账、计调审核、财务锁定、利润统计和订单显示字段。", F12, COLORS["muted"], CONTENT_W - 520, 2)

    groups = [
        ("登录与资源", [("同一用户只能同时登录一台电脑", True), ("选择地接资源时只显示本公司添加的数据", True), ("搜索操作计调默认显示自己", False), ("登录时必须修改初始密码", True)]),
        ("计调与导游", [("关闭计调界面的导游报账功能", False), ("房、车审核后计调审核才能完成", True), ("导游报账时限和计调审核提醒", True), ("设置导游报账不可见团队时间", True), ("隐藏导游报账单的当团/隔月结算", False)]),
        ("财务与利润", [("财务费用不计入利润统计", True), ("财务审核完成后限制修改数据", True), ("财务审核完成后仍允许费用变更", False), ("只能通过现金账功能进行销账", True), ("导游报账单不显示附加费用", False)]),
        ("订单与显示", [("订单管理显示接送备注/费用说明/订单备注", True), ("默认锁定团号", True), ("预控人数校验", True), ("业务代码唯一", True), ("展示散拼团队预订菜单", False), ("导游提成方式", True)]),
    ]
    group_w = (CONTENT_W - 18) // 2
    for i, (title, rules) in enumerate(groups):
        gx = CONTENT_X + (i % 2) * (group_w + 18)
        gy = y + 82 + (i // 2) * 236
        rounded(draw, (gx, gy, gx + group_w, gy + 218), 14, "#ffffff", COLORS["line"])
        draw.text((gx + 18, gy + 16), title, font=F16, fill=COLORS["blue2"])
        yy = gy + 48
        for text, checked in rules:
            draw_checkbox_item(draw, gx + 18, yy, group_w - 36, text, checked)
            yy += 36

    draw_operation_strip(draw, CONTENT_X, y + 628, CONTENT_W, item, classify(item))

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


def draw_system_log_page(item: dict[str, str], idx: int) -> Path:
    img, draw = create_canvas()
    draw_shell(draw, item)
    draw_page_header(draw, item, idx)

    y = CONTENT_Y + 88
    draw_stat_cards_for_item(draw, CONTENT_X, y, CONTENT_W - 300, item, classify(item))
    y += 100

    panel(draw, (CONTENT_X, y, CONTENT_X + CONTENT_W, y + 108), "日志管理")
    input_box(draw, CONTENT_X + 18, y + 34, 150, "姓名/用户名", "")
    input_box(draw, CONTENT_X + 188, y + 34, 170, "页面名称", "")
    input_box(draw, CONTENT_X + 378, y + 34, 220, "参数", "")
    input_box(draw, CONTENT_X + 618, y + 34, 120, "请求方法", "GET/POST")
    input_box(draw, CONTENT_X + 758, y + 34, 150, "记录时间", "2026-05-18")
    button(draw, CONTENT_X + CONTENT_W - 98, y + 56, "搜索", True)

    table_y = y + 126
    panel(draw, (CONTENT_X, table_y, CONTENT_X + CONTENT_W, table_y + 438), "系统访问日志")
    headers = ["记录编号", "页面名称", "参数内容", "IP/记录时间", "用户姓名", "请求方法"]
    ratios = [0.08, 0.18, 0.30, 0.20, 0.12, 0.12]
    tx = CONTENT_X + 18
    tw = CONTENT_W - 36
    hy = table_y + 52
    rect(draw, (tx, hy, tx + tw, hy + 38), COLORS["soft"])
    widths: list[int] = []
    cx = tx
    for header, ratio in zip(headers, ratios):
        cw = int(tw * ratio)
        widths.append(cw)
        draw_text(draw, (cx + 6, hy + 11), header, F10, COLORS["muted"], cw - 10, 2, 1)
        cx += cw
    rows = [
        ["10231", "Finance/YingshouMoney.aspx", "客户=杭州远行国旅&日期=2026-05-18", "192.168.1.21 / 05-18 10:22", CASE["finance"], "GET"],
        ["10242", "Group/BusPlan.aspx", "GroupId=261556&action=save", "192.168.1.35 / 05-18 11:05", CASE["dispatcher"], "POST"],
        ["10258", "company/RoleManage.aspx", "role=销售主管", "192.168.1.18 / 05-18 13:20", "管理员", "GET"],
        ["10263", "system/Log.aspx", "页面=日志管理", "192.168.1.18 / 05-18 13:25", "管理员", "GET"],
    ]
    ry = hy + 38
    for ridx, row in enumerate(rows):
        row_h = 74
        rect(draw, (tx, ry, tx + tw, ry + row_h), "#ffffff" if ridx % 2 == 0 else "#fbfdff")
        draw.line((tx, ry + row_h, tx + tw, ry + row_h), fill=COLORS["line2"], width=1)
        cx = tx
        for i, value in enumerate(row):
            color = COLORS["orange"] if value == "POST" else COLORS["text"]
            draw_text(draw, (cx + 6, ry + 12), value, F10, color, widths[i] - 10, 3, 2)
            cx += widths[i]
        ry += row_h

    draw_operation_strip(draw, CONTENT_X, table_y + 456, CONTENT_W, item, classify(item))

    fname = image_filename(item, idx)
    path = OUTPUT_DIR / fname
    img.save(path, quality=96)
    return path


def draw_flow_or_chart(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, h: int, kind: str):
    if kind == "统计类":
        panel(draw, (x, y, x + w, y + h), "趋势图")
        base_y = y + h - 40
        left = x + 36
        top_y = y + 60
        draw.line((left, top_y, left, base_y), fill=COLORS["line"], width=1)
        draw.line((left, base_y, x + w - 28, base_y), fill=COLORS["line"], width=1)
        pts = [(left + 28, base_y - 20), (left + 150, base_y - 48), (left + 272, base_y - 32), (left + 394, base_y - 72), (left + 516, base_y - 58)]
        for a, b in zip(pts, pts[1:]):
            draw.line((a[0], a[1], b[0], b[1]), fill=COLORS["blue"], width=4)
        for px, py in pts:
            draw.ellipse((px - 5, py - 5, px + 5, py + 5), fill=COLORS["blue"])
        return
    panel(draw, (x, y, x + w, y + h), "流程状态")
    steps = {
        "档案类": ["建档", "完善资料", "启用", "业务联动"],
        "订单团队类": ["接单", "确认", "排团", "财务"],
        "计调类": ["待安排", "资源确认", "成本审核", "可出团"],
        "财务类": ["提交", "财务审核", "收付款", "结算"],
        "系统设置类": ["配置", "审批", "启用", "留痕"],
    }.get(kind, ["提交", "审核", "处理", "完成"])
    sx = x + 40
    sy = y + 92
    gap = (w - 100) // (len(steps) - 1)
    for idx, step in enumerate(steps):
        cx = sx + idx * gap
        color = COLORS["blue"] if idx < 2 else COLORS["line"]
        draw.line((sx, sy, x + w - 60, sy), fill=COLORS["line"], width=3)
        draw.ellipse((cx - 15, sy - 15, cx + 15, sy + 15), fill=color)
        draw_text(draw, (cx - 36, sy + 26), step, F12, COLORS["text"], 72, 2)


