def draw_process_overview(items: list[dict[str, str]]) -> Path:
    img = Image.new("RGB", (W, H), COLORS["bg"])
    draw = ImageDraw.Draw(img)
    rounded(draw, (42, 42, W - 42, H - 42), 24, "#ffffff", COLORS["line"])
    draw.text((82, 82), "一个团从接单到结算", font=F36, fill=COLORS["text"])
    draw.text((82, 132), "客户与采购 -> 销售接单 -> 计调排团 -> 财务审核 -> 经营统计", font=F18, fill=COLORS["muted"])
    steps = [
        ("客户与合同", "客户建档、正式主体、合同与授信"),
        ("销售接单", "产品、团期、订单、拼团、游客名单"),
        ("计调排团", "导游、车辆、酒店、景区、票务安排"),
        ("财务审核", "应收应付、备用金、发票和收付款"),
        ("经营统计", "收客、利润、账款、资源和报表"),
    ]
    x, y = 92, 245
    card_w, card_h = 260, 210
    for idx, (title, body) in enumerate(steps):
        xx = x + idx * (card_w + 34)
        rounded(draw, (xx, y, xx + card_w, y + card_h), 20, COLORS["blue_soft"] if idx % 2 == 0 else COLORS["green_soft"], COLORS["line"])
        draw.text((xx + 24, y + 28), f"{idx + 1}. {title}", font=F22, fill=COLORS["text"])
        draw_text(draw, (xx + 24, y + 76), body, F16, COLORS["muted"], card_w - 48, 4, 10)
        draw.text((xx + 24, y + 154), "系统结果", font=F14, fill=COLORS["blue2"])
        draw_text(draw, (xx + 24, y + 180), ["确认下单资格", "形成订单应收", "形成预算成本", "进入账款闭环", "查看经营风险"][idx], F14, COLORS["text"], card_w - 48, 2)
        if idx < len(steps) - 1:
            draw.line((xx + card_w + 8, y + 104, xx + card_w + 28, y + 104), fill=COLORS["blue"], width=4)
    counts = Counter(item["优先级"] for item in items)
    draw.text((92, 555), "功能范围", font=F26, fill=COLORS["text"])
    bx = 92
    for label, value, color, bg in [
        ("P0 一期主线", counts["P0"], COLORS["red"], COLORS["red_soft"]),
        ("P1 增强/候选", counts["P1"], COLORS["blue"], COLORS["blue_soft"]),
        ("P2 后续规划", counts["P2"], COLORS["purple"], COLORS["purple_soft"]),
    ]:
        rounded(draw, (bx, 610, bx + 310, 730), 18, bg, COLORS["line"])
        draw.text((bx + 24, 632), label, font=F18, fill=color)
        draw.text((bx + 24, 670), f"{value} 项", font=F30, fill=color)
        bx += 340
    path = OUTPUT_DIR / "00-总览-业务总流程.png"
    img.save(path, quality=96)
    return path


