def draw_flow_node(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, h: int, title: str, body: str, tone: str = "blue"):
    bg = {
        "blue": COLORS["blue_soft"],
        "green": COLORS["green_soft"],
        "orange": COLORS["orange_soft"],
        "purple": COLORS["purple_soft"],
        "red": COLORS["red_soft"],
    }.get(tone, COLORS["soft"])
    color = stat_tone_color(tone)
    rounded(draw, (x, y, x + w, y + h), 18, bg, COLORS["line"])
    draw_text(draw, (x + 18, y + 16), title, F18, color, w - 36, 2, 3)
    draw_text(draw, (x + 18, y + 52), body, F13, COLORS["text"], w - 36, 3, 5)


def draw_decision_node(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, h: int, title: str, body: str):
    points = [
        (x + w // 2, y),
        (x + w, y + h // 2),
        (x + w // 2, y + h),
        (x, y + h // 2),
    ]
    draw.polygon(points, fill=COLORS["orange_soft"], outline=COLORS["orange"])
    draw_text(draw, (x + 24, y + 18), title, F16, COLORS["orange"], w - 48, 2, 2)
    draw_text(draw, (x + 24, y + 52), body, F12, COLORS["text"], w - 48, 3, 4)


def draw_flow_note_card(draw: ImageDraw.ImageDraw, x: int, y: int, w: int, h: int, title: str, lines: list[str], tone: str = "blue"):
    bg = {
        "blue": COLORS["blue_soft"],
        "green": COLORS["green_soft"],
        "orange": COLORS["orange_soft"],
        "red": COLORS["red_soft"],
    }.get(tone, COLORS["soft"])
    color = stat_tone_color(tone)
    rounded(draw, (x, y, x + w, y + h), 16, bg, COLORS["line"])
    draw_text(draw, (x + 18, y + 16), title, F16, color, w - 36, 2, 3)
    yy = y + 52
    for line in lines:
        yy = draw_text(draw, (x + 18, yy), f"• {line}", F12, COLORS["text"], w - 36, 2, 4)
        yy += 2


def draw_labeled_arrow(draw: ImageDraw.ImageDraw, start: tuple[int, int], end: tuple[int, int], label: str | None = None, color: str = "#8aa8c7", width: int = 3):
    draw_arrow(draw, start, end, color=color, width=width)
    if label:
        mx = (start[0] + end[0]) // 2
        my = (start[1] + end[1]) // 2 - 18
        rounded(draw, (mx - 42, my - 4, mx + 42, my + 20), 10, "#ffffff", COLORS["line"])
        draw_text(draw, (mx - 34, my + 2), label, F11, COLORS["muted"], 68, 1, 2)


def draw_flow_page_1(page: dict[str, object], page_no: int) -> Path:
    img, draw = create_canvas()
    rounded(draw, (42, 42, W - 42, H - 42), 24, "#ffffff", COLORS["line"])
    draw.text((82, 78), str(page["title"]), font=F36, fill=COLORS["text"])
    draw_text(draw, (82, 130), str(page["subtitle"]), F18, COLORS["muted"], W - 164, 2)

    nodes = [
        ("基础资料准备", "企业资料、客户主档、主体、合同、授信、供应商和系统参数先准备好。", "blue"),
        ("销售建团收客", "产品、团期、团队、订单、游客名单、电子合同形成销售业务单据。", "green"),
        ("计调排团履约", "围绕团队安排总控台排房、派车、订景区、安排导游和地接。", "orange"),
        ("财务审核结算", "计调审核后进入财务审核，处理应收、应付、预付款、收付款和发票。", "purple"),
        ("统计经营分析", "沉淀团队进度、收客、利润、账款、采购和经营结果。", "blue"),
    ]
    start_x, top_y, node_w, node_h, gap = 86, 252, 266, 142, 18
    centers = []
    for idx, (title, body, tone) in enumerate(nodes):
        xx = start_x + idx * (node_w + gap)
        draw_flow_node(draw, xx, top_y, node_w, node_h, title, body, tone)
        centers.append((xx + node_w, top_y + node_h // 2))
        if idx > 0:
            prev_x = start_x + (idx - 1) * (node_w + gap)
            draw_labeled_arrow(draw, (prev_x + node_w, top_y + node_h // 2), (xx, top_y + node_h // 2), "流转")

