def draw_flow_preface_page(page: dict[str, object], page_no: int) -> Path:
    if page_no == 1:
        return draw_flow_page_1(page, page_no)
    if page_no == 2:
        return draw_flow_page_2(page, page_no)
    if page_no == 3:
        return draw_flow_page_3(page, page_no)
    return draw_flow_page_4(page, page_no)


def generate_images(items: list[dict[str, str]]) -> list[Path]:
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    for old in OUTPUT_DIR.glob("*.png"):
        old.unlink()
    outputs = [draw_process_overview(items), draw_role_overview(items)]
    for page_no, page in enumerate(FLOW_PAGES, start=1):
        outputs.append(draw_flow_preface_page(page, page_no))
    for idx, item in enumerate(items, start=1):
        outputs.append(draw_prototype_page(item, idx))
    return outputs


def set_run_font(run, *, size=None, color=None, bold=None):
    run.font.name = BASE_FONT
    run._element.rPr.rFonts.set(qn("w:ascii"), BASE_FONT)
    run._element.rPr.rFonts.set(qn("w:hAnsi"), BASE_FONT)
    run._element.rPr.rFonts.set(qn("w:eastAsia"), CN_FONT)
    if size is not None:
        run.font.size = Pt(size)
    if color is not None:
        run.font.color.rgb = color
    if bold is not None:
        run.bold = bold


def add_field(paragraph, field: str):
    run = paragraph.add_run()
    set_run_font(run, size=8.5, color=RGBColor(86, 99, 116))
    fld_char_1 = OxmlElement("w:fldChar")
    fld_char_1.set(qn("w:fldCharType"), "begin")
    instr_text = OxmlElement("w:instrText")
    instr_text.set(qn("xml:space"), "preserve")
    instr_text.text = field
    fld_char_2 = OxmlElement("w:fldChar")
    fld_char_2.set(qn("w:fldCharType"), "end")
    run._r.append(fld_char_1)
    run._r.append(instr_text)
    run._r.append(fld_char_2)


def configure_doc(doc: Document):
    section = doc.sections[0]
    configure_landscape_section(section)
    for style_name in ["Normal", "Title", "Subtitle"]:
        style = doc.styles[style_name]
        style.font.name = BASE_FONT
        style.element.rPr.rFonts.set(qn("w:eastAsia"), CN_FONT)
    doc.styles["Normal"].font.size = Pt(10)
    doc.styles["Title"].font.size = Pt(24)
    doc.styles["Title"].font.bold = True
    doc.styles["Title"].font.color.rgb = RGBColor(17, 24, 39)
    doc.styles["Subtitle"].font.size = Pt(12)
    doc.styles["Subtitle"].font.color.rgb = RGBColor(86, 99, 116)
    configure_header_footer(section)


def configure_landscape_section(section):
    section.orientation = WD_ORIENT.LANDSCAPE
    section.page_width = Inches(11)
    section.page_height = Inches(8.5)
    section.top_margin = Inches(0.34)
    section.bottom_margin = Inches(0.34)
    section.left_margin = Inches(0.42)
    section.right_margin = Inches(0.42)
    section.header_distance = Inches(0.16)
    section.footer_distance = Inches(0.16)


def configure_tall_section(section):
    section.orientation = WD_ORIENT.PORTRAIT
    section.page_width = Inches(11)
    section.page_height = Inches(21)
    section.top_margin = Inches(0.34)
    section.bottom_margin = Inches(0.34)
    section.left_margin = Inches(0.42)
    section.right_margin = Inches(0.42)
    section.header_distance = Inches(0.16)
    section.footer_distance = Inches(0.16)


def configure_header_footer(section):
    header = section.header.paragraphs[0]
    header.alignment = WD_ALIGN_PARAGRAPH.LEFT
    header.text = ""
    r = header.add_run("旅游接待管理系统 | 甲方菜单页面原型图册")
    set_run_font(r, size=8.5, color=RGBColor(86, 99, 116))
    footer = section.footer.paragraphs[0]
    footer.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    footer.text = ""
    r = footer.add_run("第 ")
    set_run_font(r, size=8.5, color=RGBColor(86, 99, 116))
    add_field(footer, "PAGE")
    r = footer.add_run(" 页")
    set_run_font(r, size=8.5, color=RGBColor(86, 99, 116))


def add_para(doc: Document, text: str, *, size=10, color=RGBColor(17, 24, 39), bold=False, after=4, align=None):
    p = doc.add_paragraph()
    if align is not None:
        p.alignment = align
    p.paragraph_format.space_after = Pt(after)
    r = p.add_run(clean(text))
    set_run_font(r, size=size, color=color, bold=bold)
    return p


def add_cover(doc: Document, items: list[dict[str, str]], source_count: int):
    add_para(doc, "旅游接待管理系统", size=28, bold=True, after=4)
    add_para(doc, "甲方菜单页面原型图册", size=18, color=RGBColor(46, 116, 181), bold=True, after=14)
    statement = "本图册为页面原型图，用于业务确认和范围沟通，不代表系统已开发完成，也不是最终 UI 视觉稿。"
    supplement_count = sum(1 for item in items if clean(item.get("补充页")) == "是")
    role_page_count = sum(1 for item in items if item.get("模块") == "导游端")
    main_count = len(items) - supplement_count - role_page_count
    rows = [
        ("图册用途", "给甲方确认功能页面形态、业务范围和关键页面能力。"),
        ("生成依据", "旅游接待管理系统-功能建设清单-完整保留版.xlsx"),
        ("覆盖范围", f"共 {main_count} 个主功能原型页面、{supplement_count} 张补充页面、1 张导游端微信小程序角色页面、2 张总览页、4 张业务流程页，基于 Excel {source_count} 项功能生成；客户分类与客户等级、客户下单名称与正式主体确认已合并到客户主档页面；客户可售产品授权、车辆资源与日期排班管理、车辆日历、酒店资源基础库、酒店房源日期与房调管理、景区资源基础库、地接外委管理、多订单共车成本分摊不单独成页；车辆与酒店采购能力已并入计调主页面展示；产品新增与编辑、产品团队安排参数总图、团期资源安排自动化逻辑图、团队安排顶部工具按钮说明、普通按钮逻辑明细页、高风险按钮逻辑明细页、下单校验与业务规则提醒、团队预付款作为补充页面单独展示；导游端 / 微信小程序报账与核销放在全册最后，地接服务和共车分摊规则并入团队安排自动化逻辑图。"),
        ("原型说明", statement),
        ("生成日期", date.today().isoformat()),
    ]
    table = doc.add_table(rows=len(rows), cols=2)
    table.autofit = False
    for idx, (k, v) in enumerate(rows):
        table.rows[idx].cells[0].width = Inches(1.4)
        table.rows[idx].cells[1].width = Inches(8.6)
        set_cell(table.rows[idx].cells[0], k, bold=True, fill="F2F4F7", color=RGBColor(31, 77, 120))
        set_cell(table.rows[idx].cells[1], v)


def set_cell(cell, text: str, *, bold=False, fill=None, color=RGBColor(17, 24, 39), size=9.5):
    if fill:
        tc_pr = cell._tc.get_or_add_tcPr()
        shd = tc_pr.find(qn("w:shd"))
        if shd is None:
            shd = OxmlElement("w:shd")
            tc_pr.append(shd)
        shd.set(qn("w:fill"), fill)
    cell.text = ""
    p = cell.paragraphs[0]
    p.paragraph_format.space_after = Pt(0)
    r = p.add_run(clean(text))
    set_run_font(r, size=size, color=color, bold=bold)


def add_compact_form_cell(cell, label: str, text: str):
    set_cell(cell, "", fill="F8FAFC")
    p = cell.paragraphs[0]
    p.paragraph_format.space_after = Pt(1)
    r = p.add_run(clean(label))
    set_run_font(r, size=9.2, color=RGBColor(31, 77, 120), bold=True)

    p2 = cell.add_paragraph()
    p2.paragraph_format.space_before = Pt(1)
    p2.paragraph_format.space_after = Pt(0)
    r2 = p2.add_run(clean(text))
    set_run_font(r2, size=8.6, color=RGBColor(17, 24, 39))


def add_page_form(doc: Document, usage: str, operations: str):
    table = doc.add_table(rows=1, cols=2)
    table.autofit = False
    table.rows[0].cells[0].width = Inches(5.0)
    table.rows[0].cells[1].width = Inches(5.0)
    add_compact_form_cell(table.rows[0].cells[0], "页面作用与功能", usage)
    add_compact_form_cell(table.rows[0].cells[1], "页面操作", operations)
    doc.add_paragraph().paragraph_format.space_after = Pt(1)


def add_image_page(doc: Document, title: str, body: str, image_path: Path, *, operations: str = "", page_break=True):
    if page_break:
        doc.add_page_break()
    add_para(doc, title, size=15.5, color=RGBColor(46, 116, 181), bold=True, after=2)
    if body or operations:
        add_page_form(doc, body, operations)
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_after = Pt(0)
    run = p.add_run()
    run.add_picture(str(image_path), width=Inches(9.62))


def add_tall_image_page(doc: Document, title: str, body: str, image_path: Path, *, operations: str = ""):
    section = doc.add_section()
    configure_tall_section(section)
    configure_header_footer(section)
    add_para(doc, title, size=15.5, color=RGBColor(46, 116, 181), bold=True, after=2)
    if body or operations:
        add_page_form(doc, body, operations)
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.space_after = Pt(0)
    run = p.add_run()
    run.add_picture(str(image_path), width=Inches(9.62))


def next_versioned_docx_path() -> Path:
    DOCX_PATH.parent.mkdir(parents=True, exist_ok=True)
    existing = sorted(DOCX_PATH.parent.glob(f"{DOCX_VERSION_PREFIX}[0-9][0-9][0-9].docx"))
    versions: list[int] = []
    for path in existing:
        version_text = path.stem.replace(DOCX_VERSION_PREFIX, "")
        if version_text.isdigit():
            versions.append(int(version_text))
    return DOCX_PATH.parent / f"{DOCX_VERSION_PREFIX}{(max(versions) + 1 if versions else 1):03d}.docx"


def build_doc(items: list[dict[str, str]], image_paths: list[Path], source_count: int) -> Path:
    DOCX_PATH.parent.mkdir(parents=True, exist_ok=True)
    doc = Document()
    configure_doc(doc)
    add_cover(doc, items, source_count)
    add_image_page(doc, "总览页 1：一个团从接单到结算", "", image_paths[0])
    add_image_page(doc, "总览页 2：岗位视角", "", image_paths[1])
    flow_titles = [
        "流程页 1：系统全流程图",
        "流程页 2：销售业务流程图",
        "流程页 3：计调履约流程图",
        "流程页 4：财务结算与关键控制点",
    ]
    flow_descs = [
        "先看系统主链：基础资料、销售建团、计调排团、财务结算、经营统计如何接起来。",
        "用于说明销售阶段如何从客户、产品、团期一路形成团队、订单和游客资料。",
        "用于说明计调如何以团队安排总控台为中心，优先落实房子和车子，再补齐其它履约资源。",
        "用于说明财务如何承接团队审核结果，完成应收应付、预付款、收付款与锁定规则闭环。",
    ]
    for offset, (title, desc) in enumerate(zip(flow_titles, flow_descs), start=2):
        add_image_page(doc, title, desc, image_paths[offset])
    previous_was_tall = False
    for idx, item in enumerate(items, start=1):
        title = f"{display_no(item, idx)}. {item['模块']} / {client_title(item)}"
        if item.get("编号") in {"S02-AUTO", "S02-TOOLS", "S02-OPS-DETAIL", "S02-OPS-RISK", "S03", "S04", "S04-RULES", "S06", "D07", "D07-MINI", "F09"}:
            add_tall_image_page(doc, title, page_usage(item), image_paths[idx + 5], operations=page_operations(item))
            previous_was_tall = True
        else:
            if previous_was_tall:
                section = doc.add_section()
                configure_landscape_section(section)
                configure_header_footer(section)
                add_image_page(doc, title, page_usage(item), image_paths[idx + 5], operations=page_operations(item), page_break=False)
                previous_was_tall = False
            else:
                add_image_page(doc, title, page_usage(item), image_paths[idx + 5], operations=page_operations(item))
    props = doc.core_properties
    props.title = "旅游接待管理系统-甲方菜单页面原型图册"
    props.subject = "手绘高保真页面原型图"
    props.author = "Codex"
    versioned_path = next_versioned_docx_path()
    doc.save(versioned_path)
    copyfile(versioned_path, DOCX_PATH)
    return versioned_path


def validate(source_items: list[dict[str, str]], items: list[dict[str, str]], images: list[Path], docx_path: Path = DOCX_PATH):
    if len(source_items) != 67:
        raise RuntimeError(f"Expected 67 Excel source items, got {len(source_items)}")
    if len(items) != 68:
        raise RuntimeError(f"Expected 68 prototype pages after C01/C02/C04 merge, C06/P05/P06/P08/P09/S07 removal and supplement-page insertions, got {len(items)}")
    if any(item.get("编号") in {"C02", "C04", "C06", "P05", "P05-CAL", "P06", "P07", "P08", "P09", "S07"} for item in items):
        raise RuntimeError("Merged or removed procurement/support pages should not be emitted as standalone pages")
    first = items[0]
    merged_features = split_features(first.get("具体功能", ""), 20)
    for expected in ["客户分类", "A/B客户等级", "默认授信额度", "分类统计", "原始下单名称", "正式法律主体", "开票主体", "结算主体"]:
        if expected not in merged_features:
            raise RuntimeError(f"Customer master merged feature missing: {expected}")
    modules = list(dict.fromkeys(item["模块"] for item in items))
    if modules != MODULE_ORDER:
        raise RuntimeError(f"Unexpected module order: {modules}")
    validate_profiles(items)
    if len(images) != 74:
        raise RuntimeError(f"Expected 74 images including 2 overview pages, 4 flow pages and 68 prototype pages, got {len(images)}")
    expected_flow = [f"00-流程页-{idx:02d}.png" for idx in range(1, 5)]
    image_names = [image.name for image in images]
    missing_flow = [name for name in expected_flow if name not in image_names]
    if missing_flow:
        raise RuntimeError(f"Missing flow preface images: {missing_flow}")
    if any("客户下单名称与正式主体确认" in image.name for image in images):
        raise RuntimeError("C04 subject confirmation image should not be emitted as a standalone page")
    if any("客户可售产品授权" in image.name for image in images):
        raise RuntimeError("C06 product authorization image should not be emitted as a standalone page")
    if any("车辆资源与日期排班管理" in image.name for image in images):
        raise RuntimeError("Vehicle resource/date schedule image should not be emitted as a standalone page")
    if any("车辆日历" in image.name for image in images):
        raise RuntimeError("Vehicle calendar image should not be emitted as a standalone page")
    if any("酒店资源基础库" in image.name for image in images):
        raise RuntimeError("Hotel resource base image should not be emitted as a standalone page")
    if any("酒店房源日期与房调管理" in image.name for image in images):
        raise RuntimeError("Hotel room adjustment image should not be emitted as a standalone page")
    if any("景区资源基础库" in image.name for image in images):
        raise RuntimeError("P08 scenic resource base image should not be emitted as a standalone page")
    if any("地接外委管理" in image.name for image in images):
        raise RuntimeError("P09 local operator outsourcing image should not be emitted as a standalone page")
    if not any("新增与编辑产品" in image.name for image in images):
        raise RuntimeError("Product create/edit page should be emitted as a standalone page")
    if not any("产品团队安排参数总图" in image.name for image in images):
        raise RuntimeError("Product resource map page should be emitted as a standalone page")
    if not any("团期资源安排自动化逻辑图" in image.name for image in images):
        raise RuntimeError("Team resource automation page should be emitted as a standalone page")
    if not any("团队安排顶部工具按钮说明" in image.name for image in images):
        raise RuntimeError("Team arrangement toolbar page should be emitted as a standalone page")
    if not any("团队预付款" in image.name for image in images):
        raise RuntimeError("Team imprest page should be emitted as a standalone page")
    if any("团队操作台规则与下游影响图" in image.name for image in images):
        raise RuntimeError("Team operation rules page should not be emitted as a standalone page")
    if not any("普通按钮逻辑明细页" in image.name for image in images):
        raise RuntimeError("Team operation button detail page should be emitted as a standalone page")
    if not any("高风险按钮逻辑明细页" in image.name for image in images):
        raise RuntimeError("Team operation risk detail page should be emitted as a standalone page")
    if not any("下单校验与业务规则提醒" in image.name for image in images):
        raise RuntimeError("Order validation rules page should be emitted as a standalone page")
    automation_image = next((image for image in images if "团期资源安排自动化逻辑图" in image.name), None)
