def validate_profiles(items: list[dict[str, str]]):
    required = {"kind_label", "usage", "operations", "stats", "filters", "headers", "rows", "details", "cards", "actions"}
    missing: list[str] = []
    invalid: list[str] = []
    generic_operation_markers = [
        "新增业务单，确认订单，补充游客名单",
        "安排导游、车辆、酒店、门票等资源",
        "审核应收应付和成本，核验凭证",
        "筛选统计口径，查看指标明细",
        "配置业务参数、审批节点、预警规则",
    ]
    for idx, item in enumerate(items, start=1):
        if idx < 4:
            continue
        item_profile = profile_for(item)
        if not item_profile:
            missing.append(f"{idx:02d} {item['编号']} {item['模块']} / {client_title(item)}")
            continue
        absent = sorted(required - set(item_profile))
        headers = list(item_profile.get("headers", []))
        rows = [list(row) for row in item_profile.get("rows", [])]
        actions = item_profile.get("actions")
        if absent or len(headers) != 5 or len(rows) < 3 or any(len(row) != len(headers) for row in rows) or not isinstance(actions, tuple) or len(actions) != 2:
            invalid.append(f"{idx:02d} {item['编号']} invalid profile: missing={absent}, headers={len(headers)}, rows={len(rows)}")
        operations = str(item_profile.get("operations", ""))
        if any(marker in operations for marker in generic_operation_markers):
            invalid.append(f"{idx:02d} {item['编号']} generic operation text remains")
        usage = str(item_profile.get("usage", ""))
        if item["模块"] not in {"数据统计", "企业资料", "系统设置"} and raw_title(item)[:2] not in usage:
            # Page-specific profiles do not need to repeat the title, but must be long enough to explain the actual page.
            if len(usage) < 40:
                invalid.append(f"{idx:02d} {item['编号']} usage too short")
    if missing:
        raise RuntimeError("Missing page profiles after page 04:\n" + "\n".join(missing))
    if invalid:
        raise RuntimeError("Invalid page profiles:\n" + "\n".join(invalid))


def main():
    source_items = read_items()
    items = merge_customer_master_items(source_items)
    images = generate_images(items)
    versioned_path = build_doc(items, images, len(source_items))
    validate(source_items, items, images, DOCX_PATH)
    validate(source_items, items, images, versioned_path)
    print(versioned_path)
    print(DOCX_PATH)
    print(OUTPUT_DIR)
    print(len(images))


if __name__ == "__main__":
    main()
